-- Generated by scripts/pages.ts from i18n/frFR/recipes/: edit those, not this file.
-- pages[chef][spell] = { paragraph, ... }: the chef's page of each dish.
local _, ns = ...
ns.pages = {
  kendor = {
    [2538] = { "Tout cuisinier commence ici, avec un feu, un couteau et un loup qui n'avait aucune envie de finir en dîner. La plupart n'en sortent jamais, et c'est ainsi que les routes de ce royaume se sont mises à sentir le loup brûlé. Griller n'est pas brûler. Vous voulez l'extérieur sombre et croustillant, l'intérieur encore tendre, et cela suppose un feu retombé en braises, pas un feu qui fait encore le fier avec ses flammes. Apprenez cela et vous aurez appris la patience. Ensuite, venez me voir." },
    [2539] = { "Le deuxième plat que tout maître enseigne, et le premier que la plupart des cuisiniers ratent. Ils croient que l'épice est un déguisement. Ils prennent un loup qui s'est usé à courir dans les collines et ils l'ensevelissent, alors que le loup méritait mieux. Frottez l'épice avant que la viande ne rencontre le feu, puis laissez-la reposer. L'épice ajoutée à la fin se pose sur la viande comme un chapeau. Ajoutée au début, elle en fait partie." },
    [2540] = { "Les sangliers d'Elwynn nourrissent cette ville depuis avant qu'elle ait des murs, et ils la nourriront encore quand il faudra rebâtir les murs. Tomas, à Comté-de-l’Or, les rôtit entiers pour son auberge en tournant la broche à la main, et il appelle cela la tradition. C'est une belle tradition. C'est aussi pourquoi son sanglier est cuit d'un côté et plein d'espoir de l'autre. Coupez la viande en morceaux égaux, pour que la chaleur les traite tous de la même façon. En cuisine, la justice est affaire de couteau." },
    [2541] = { "Les coyotes de la Marche de l'Ouest mangent ce que les fermiers ont laissé derrière eux, et leur viande a le goût d'une vie difficile. Vous ne pouvez pas changer son passé. Vous pouvez le respecter. Taillez le steak épais, saisissez-le fort et retirez-le du feu tant que le coeur rosit encore. Un steak de coyote mince et cuit à coeur, c'est une sandale. Un steak épais et reposé, c'est un souper. Chaque apprenti arrive persuadé qu'un steak est une chose simple. C'en est une. C'est bien pour cela qu'il est si facile à rater." },
    [2542] = { "La tourte au foie de Broche-tripes est la fierté des fermes de la Marche de l'Ouest, ou l'était, quand il y avait des fermes dont être fier. Une fermière de la route côtière l'a apprise à la moitié de la province, et je la vends ici avec quelques corrections qu'elle n'est pas encore venue contester à Hurlevent. Le foie d'un Broche-tripes est fort, sombre et riche, et il faut le faire tremper dans l'eau froide avant de le cuire, pour en tirer l'amertume. Puis une pincée d'épices douces et un four doux. Le foie cuit vite devient gris et granuleux et a le goût du fer. Le foie cuit lentement devient tendre et doux et a le goût de la ferme d'où il vient. La croûte est affaire d'opinion. Le foie ne l'est pas. Quand la tourte sort du four, laissez-la reposer jusqu'à ce qu'elle cesse de chuchoter. Puis coupez-la, et la fierté vous sera alors permise." },
    [2543] = { "Je vends la recette de ce ragoût, ce qui vous dit que je l'approuve, comme on approuve une bonne paire de bottes. Les fermiers de la Marche de l'Ouest le faisaient avec ce que la terre leur jetait, le vautour, le groin d'un Broche-tripes, l'oeil de murloc, et ils avaient raison sur les trois. Je l'ai essayé une fois sans l'oeil. Il était maigre, et mon orgueil aussi. C'est l'oeil qui donne du corps au bouillon. Laissez-le mijoter plus longtemps que vous ne le pensez, puis plus longtemps encore. Un ragoût bâclé n'est qu'une soupe qui a menti. Aujourd'hui, les fermes sont vides, et ce ragoût est cuisiné par ceux qui les ont perdues, dans les camps qui bordent la route de la Colline des sentinelles. Il n'a rien de raffiné. Il est honnête, et dans la Marche de l'Ouest, c'est devenu plus rare que le raffinement." },
    [2544] = { "Tous les maîtres enseignent les beignets de crabe, et tous les enseignent trop humides. De la chair de clampant bien nettoyée, une pincée d'épices douces, le tout pressé à la main et rien d'autre, puis frit jusqu'à ce que l'extérieur prenne en une croûte qui tient le reste. S'il s'effondre, vous n'avez pas assez pressé. S'il rebondit, vous avez trop pressé. Un beignet de crabe doit être ferme comme une poignée de main est ferme, et pas davantage." },
    [2545] = { "La côte de la Marche de l'Ouest grouille de crabes, et les contrebandiers défias qui s'y cachent m'ont, dit-on, volé ma recette pour leurs pinces. J'en suis flatté. Une pince doit être fendue avant de rencontrer le feu, pour que la chaleur atteigne la chair au lieu de la cuire à la vapeur dans sa propre armure. Une pincée d'épices douces dans la fente. Un feu bref et chaud. Puis tirez la chair à la fourchette, et rappelez-vous que même les voleurs mangent bien quand ils volent le bon cuisinier." },
    [2546] = { "Les côtes sèches sont un plat de fermier, des côtes de sanglier et une friction d'épices, sans la moindre sauce. Certains cuisiniers en ont peur. Ils croient qu'une côte doit dégouliner pour être bonne. Une côte doit être cuite pour être bonne. Frottez l'épice la veille, laissez le feu retomber jusqu'à une lueur sourde et donnez aux côtes l'après-midi entier. Elles en sortent sombres, croustillantes et sèches au toucher, et ne laissent rien sur l'os." },
    [2547] = { "Le goulash des Carmines, c'est de l'araignée et du condor, mijotés ensemble par les gens de Comté-du-Lac, qui ont des araignées et des condors à revendre depuis que les gnolls ont pris le reste. Les deux viandes ne cuisent pas à la même vitesse. Mettez le condor d'abord, parce qu'il est coriace, et l'araignée plus tard, parce qu'elle ne l'est pas. Cuites ensemble dès le départ, vous aurez une viande gâchée et l'autre crue. Je vends la recette avec cet avertissement écrit dans la marge, de ma main." },
    [2548] = { "Les gnolls des Carmines trimballent cette recette dans leurs sacs, volée dans quelque ferme, et n'en font rien. Je vends la même recette à Hurlevent et j'en fais beaucoup. Deux portions de côtes de sanglier et des épices fortes, et tout le secret est de les retourner. Retournez-les toutes les quelques minutes, pour que la graisse arrose la viande en fondant. Le moelleux n'est pas une promesse du nom. C'est une récompense de l'attention." },
    [2549] = { "Voilà le plat auquel je mettrais mon nom, et je l'ai fait. Du steak de loup et des herbes aromatiques de Stormwind, rien d'autre, et quiconque vous propose de remplacer les herbes a quelque chose à vous vendre. Laissez un espace entre les morceaux sur la brochette, pour que la chaleur atteigne chaque face. Laissez-le reposer avant de le manger. Un kébab arraché trop tôt au feu pleure dans l'assiette, et vous pleurerez avec lui." },
    [2795] = { "Ragnar Thunderbrew croit que cette recette appartient à sa famille. Je la vends à Hurlevent à un prix honnête, et je l'ai améliorée. Il vous dira que les côtes veulent leur bière au malt Rhapsody de la première minute à la dernière. C'est faux. Les nains arrosent dès le début, puis se demandent pourquoi l'extérieur brûle pendant que l'intérieur boude. Rôtissez les côtes à nu jusqu'à ce que la graisse coule claire, et alors seulement commencez la bière, un peu à la fois, pour qu'elle devienne un glaçage et non du charbon. Le résultat est sucré, sombre et collant, et c'est ce que Dun Morogh a produit de mieux. Je le dirais bien à Ragnar, s'il pouvait entendre quoi que ce soit par-dessus le vacarme de sa propre taverne. Je soupçonne qu'il le sait. Ses côtes se sont améliorées depuis." },
    [3370] = { "Le crocilisque est le steak de ceux qui trouvent le boeuf trop complaisant. Les Paluns en regorgent, et les chasseurs du port de Menethil m'apportent les queues dans des tonneaux de saumure. La viande est pâle et ferme, plus proche du poisson que de la bête. Cuisez-la comme un poisson épais : chaud, vite, et jamais deux fois. Le crocilisque réchauffé a le goût du marais d'où il vient, et personne n'a jamais demandé ce goût-là." },
    [3371] = { "Les nains de Thelsamar font le boudin chaque hiver et en envoient quelques-uns à Forgefer, où Daryl Riknussun les vante bruyamment avant d'apprendre à ses élèves à les faire moins bien. Je vends ici la recette, corrigée. De la viande d'ours, des tripes de sanglier nettoyées et de l'ichor d'araignée, qui lie comme le sang le faisait et se conserve bien mieux. Remplissez le boyau sans trop serrer. Un boudin trop serré éclate dans la poêle et se vide sur les braises, et personne n'a jamais aimé un boudin qui abandonne." },
    [3372] = { "Les ailerons de murloc donnent une soupe qui a plus de corps que vous ne le croiriez, si vous n'avez croisé les murlocs qu'au bout d'une épée. Deux ailerons et des épices fortes, mijotés jusqu'à ce que les ailerons fondent dans le bouillon et lui donnent une richesse digne du meilleur fond d'os. Les murlocs, je le soupçonne, protesteraient. Les murlocs protestent contre tout, longuement, et jamais dans une langue que je tienne à apprendre." },
    [3373] = { "Le gombo est un plat des marais, un ragoût épais et sombre que les gens des Paluns cuisinent comme si leur vie en dépendait, ce qui, aux Paluns, arrive parfois. De la viande de crocilisque tendre et des épices fortes, réduites jusqu'à ce que le bouillon soit sombre et assez épais pour napper une cuillère. La couleur est la mesure. Trop pâle, on l'a pressé. Trop sombre, vous avez brûlé le fond de la marmite et devriez recommencer avec dignité." },
    [3376] = { "Au goût étrange, c'est le nom le plus honnête de mon catalogue, car tous ceux qui la mangent se demandent pourquoi elle est si bonne. C'est un oeuf de raptor, bien plus riche que celui d'une poule, et des épices fortes. Battez-le fort, cuisez-le vite et pliez-le baveux. Un oeuf de raptor prend plus lentement que celui d'une poule, alors prenez patience avec le coeur. L'étrangeté est méritée. L'omelette est la mienne, par droit d'amélioration." },
    [3377] = { "Je vends une recette appelée tourte d'araignée fondante, et je la vends sans sourire, parce qu'elle est très bonne. Deux pattes d'araignée fondantes, la chair tirée et mêlée d'épices fortes, pressée en galettes et frite jusqu'à ce que l'extérieur croustille et que l'intérieur reste tendre. Le fondant est dans le nom et doit rester au coeur. Une galette qui coule a été frite trop chaud. Les gens du Bois de la Pénombre en mangent à la douzaine, ce qui est la chose la plus courageuse que je sache du Bois de la Pénombre." },
    [3397] = { "Les ours d'Orneval deviennent plus grands que les nôtres, nourris de la patience des elfes de la nuit et de ce qu'ils trouvent sous les arbres. Leur viande est sombre et riche et réclame une épice forte pour la trancher. Saisissez-la fort et laissez-la reposer longtemps, plus longtemps qu'un animal plus petit, car un gros steak continue de cuire une fois sorti du feu. En Désolace, me dit-on, une machine gobeline vend mes recettes un exemplaire à la fois. J'aimerais rencontrer son cuisinier." },
    [3398] = { "Des lions des Tarides, coupés en côtelettes et brûlés aux épices fortes par des cuisiniers qui appellent le résultat un mets de choix. J'appelle cela un lion qui méritait mieux. La viande de lion est maigre et douce près de l'os, et c'est pour cela qu'il faut cuire la côtelette sur l'os. L'épice forte est la bienvenue. Le feu fort ne l'est pas. Donnez aux côtelettes une chaleur modérée et retournez-les souvent. Un lion doit arriver à table avec l'air d'avoir perdu un combat loyal." },
    [3399] = { "Délicieux, se dit-il, et c'est trop modeste de moitié. Deux morceaux de lion et des épices apaisantes, cuits en steak plutôt qu'en côtelettes, ce qui est la seule façon civilisée de manger un lion. L'épice apaisante n'est pas là pour calmer le cuisinier. Elle arrondit la douceur de la viande. Saisissez, laissez reposer, tranchez contre le fil. Un steak de lion tranché dans le sens du fil se mâche comme une dispute qu'on ne peut pas gagner." },
    [3400] = { "Une bisque est une soupe lisse, et la bisque de tortue est lisse parce que la tortue a abandonné tout ce qu'elle avait à donner. De la viande de tortue et des épices apaisantes, mijotées des heures, puis passées au tamis jusqu'à ce qu'il ne reste rien qu'une cuillère puisse accrocher. Le tamis, c'est la recette. Sautez-le et vous aurez une soupe de tortue, ce qui est une chose différente et moindre. Apaisante, dit-elle d'elle-même. Je dirais patiente, et j'aurais raison." },
    [4094] = { "Dans les Terres ingrates, on vous dira qu'un busard ne vaut pas les braises. Ils ne l'ont pas mangé grillé. Une aile de busard n'est que tendon et rancune : il lui faut des épices fortes et une longue chaleur douce, puis une flambée brève et féroce à la fin pour cloquer la peau. Les chasseurs d'Arathi vendent la recette pour une bouchée de pain, ce qui est un crime contre la cuisine, et je ne l'ai signalé à personne." },
    [6412] = { "Les elfes de la nuit de Teldrassil vous enseigneront ce kébab pour le prix de quelques pattes d'araignée, ce qui vous dit ce qu'ils pensent des araignées. Alegorn, à Darnassus, voudrait que vous enfiliez chaque patte avec un brin de verdure et que vous disposiez les brochettes comme un poème. Oubliez le poème. Les pattes d'araignée veulent une chaleur vive et brève, juste de quoi fendre la carapace, sinon la chair se change en ficelle. Ensuite, garnissez si vous y tenez. Je n'y tiens jamais." },
    [6413] = { "Un plat de la Horde, venu de la poussière de Durotar, et la surprise, c'est qu'on puisse manger un scorpide exprès. Je n'ai nul besoin de goûter la cuisine d'Orgrimmar. J'en ai cependant lu la recette, car un maître lit tout. Sa seule sagesse tient au dard. Cuit jusqu'à passer du verre à la craie, il perd son venin et garde son mordant. Pas assez cuit, il garde les deux. Je vous laisse juger lequel des deux mérite le nom de surprise." },
    [6414] = { "Le kodo est la viande de Mulgore, rôtie là-bas par des taurens qui cuisinent sous le ciel ouvert, avec les plaines pour cuisine. Je ne me suis jamais tenu sous ce ciel et je n'en ai pas l'intention. Un kodo est un animal énorme et patient, et sa viande l'est aussi : dure au début, généreuse à la fin. Rôtissez-la lentement et laissez-la reposer aussi longtemps qu'elle a rôti. Les taurens ont raison sur un point, et le voici : certaines viandes ne se pressent pour personne." },
    [6415] = { "Les furies de Sombrivage ne sont que dents et colère, et les elfes de la nuit les découpent en filets avec une révérence que je trouve excessive. Alegorn voudrait que vous posiez le filet sur une feuille et que vous murmuriez au-dessus. Je voudrais que vous l'assaisonniez légèrement et que vous le cuisiez vite, car la chair de furie est molle et se défait si vous la regardez trop lentement. Côté peau, poêle chaude, un seul retournement. La feuille est facultative. Le murmure ne me regarde pas." },
    [6416] = { "Le trotteur est l'oiseau aux longues pattes des Tarides, tout en cou et en opinions, et la Horde le fait mijoter avec des pommes, ce qui est la première chose sensée que j'aie entendu dire d'eux. La pomme adoucit le bouillon et attendrit la viande, et la viande en a besoin. Laissez mijoter lentement jusqu'à ce que la pomme ait disparu et que l'oiseau ait renoncé à son entêtement. Je ne traverserais pas la mer pour lui. Je ne le refuserais pas non plus." },
    [6417] = { "Un brouet de rats, enseigné par la Horde dans les Tarides à quiconque leur attrape les rats. Je l'inclus parce que je suis consciencieux, pas parce que je le recommande. Un rat fouisseur est petit et maigre et, me dit-on, plus propre que les rats de nos égouts, ce qui est un maigre éloge. Faites-le mijoter longtemps. Tout dans ce plat appelle une longue cuisson, y compris le besoin qu'a le cuisinier d'oublier ce qu'il y a dans la marmite." },
    [6418] = { "Un plat des Tarides, vendu à la Croisée et mangé par la Horde avec les doigts. Je ne mentionne les doigts que pour que vous ne les imitiez pas. Une queue de lézard-tonnerre n'est que muscle, et le croquant vient de la cuisson dans sa propre graisse, jusqu'à ce que la peau éclate. Des épices fortes, une poêle brûlante, et un cuisinier assez courageux pour l'y laisser. Je ne prétendrai pas admirer les Tarides. J'admettrai que la queue est bien pensée." },
    [6419] = { "La venaison est la viande d'un cuisinier bien élevé. Un cerf est maigre et fier et doit être traité comme tel, avec beaucoup d'épices bien frottées et très peu de temps sur le feu. Faites trop cuire un cerf et vous avez insulté la forêt. Les elfes d'Orneval vendent cette recette, ce que je trouve touchant, eux qui passent tant de leur vie à empêcher quiconque de chasser leurs cerfs. Cuisez-la saignante, tranchez-la fin et ne dites rien de sa provenance." },
    [6499] = { "Une palourde, c'est une bouchée de mer, et la seule façon de la gâcher est de l'oublier dans la marmite. Ce que tout le monde fait. Les marins du port les font bouillir dans l'eau de mer et appellent cela une tradition. J'appelle cela de la paresse avec vue sur le large. Prenez une bonne eau de source, comptez lentement jusqu'à soixante et sortez-les. Le caoutchouc, c'est pour les bottes. Si vous ressentez le besoin d'une sauce, c'est que vous les avez trop cuites." },
    [6500] = { "Les gobelins préparent leurs palourdes comme ils font des affaires : avec trop de chaleur et beaucoup de bruit. J'enseigne la recette malgré tout, la chaleur corrigée. De la chair de palourde relevée, des épices fortes et un feu chaud sans être furieux. Une palourde cuite avec fureur devient du cuir. Une palourde bien cuite garde juste assez de combat pour vous rappeler qu'elle vient de la mer. Les gobelins vous feraient payer le cuir deux fois plus cher." },
    [6501] = { "Une soupe de palourdes, ce sont des palourdes et du lait, et le lait ne doit jamais bouillir. C'est toute la difficulté, et elle suffit à vaincre la plupart des cuisiniers de la côte. Chauffez doucement le lait glacé, ajoutez la chair de palourde et une pincée d'épices douces, et gardez le tout sous le frémissement jusqu'à ce que les palourdes soient tout juste cuites. Le lait bouilli tranche, et une soupe tranchée ressemble à une erreur dans un bol. Les poissonnières de la Marche de l'Ouest la réussissent plus souvent que les auberges. Les auberges devraient avoir honte." },
    [7213] = { "Les cuisiniers de Baie-du-Butin font flamber une palourde géante dans des épices fortes et la servent aux pirates, qui mangeraient n'importe quoi qui ne mord pas en retour, et plusieurs choses qui mordent. Je l'ai affinée. La chair de palourde géante est dense et douce, et l'astuce est de la trancher fin avant que la chaleur ne la touche, pour que l'épice la traverse. Puis le feu, fort et vite. Une ardeur doit roussir les sourcils du cuisinier et épargner la palourde." },
    [7751] = { "Le premier poisson de tout enfant muni d'une canne, et le premier poisson que bien des cuisiniers ne dépassent jamais. Un goujon, c'est une bouchée, et une bouchée ne pardonne rien. Cuisez-le entier, dans une poêle chaude, et seulement jusqu'à ce que l'oeil se trouble. C'est votre horloge, et le poisson la porte pour vous. Les pêcheurs du port les vendent au seau aux enfants, qui les brûlent. Je ne les vends pas. Je les corrige." },
    [7752] = { "Le maquereau est un poisson gras, et la graisse est un cadeau que la plupart des cuisiniers traitent comme un problème. Ils la noient, ils la grattent, ils s'en excusent. Posez-le côté peau dans une poêle sèche et brûlante, et laissez sa propre graisse le cuire. La peau croustille, la chair reste douce, et la cuisine sent la mer pendant une journée, ce qui n'a rien d'une punition. J'ai appris cela sur les quais, enfant. Je ne l'ai qu'un peu amélioré, ce qui, venant de moi, est un compliment." },
    [7753] = { "Un lutjan des fonds vaseux des rivières lentes, et il en a le goût, à moins de savoir mieux faire. Je sais mieux faire. Nettoyez-le bien, cuisez-le entier sur un feu modéré et retirez la peau avant de servir. La vase est dans la peau, pas dans la chair. Les pêcheurs le mangent avec la peau et vous disent que la rivière fait partie du charme. La rivière fait partie de la rivière. Laissez-la là où elle est." },
    [7754] = { "Les nains du Loch Modan ont appelé ce plat un délice, ce qui est le mot le plus généreux que j'aie jamais entendu un nain employer pour une chose qui ne contient pas de malt. La furie du loch est plus ferme que ses cousines du sud, une chair d'eau froide qui se tient dans la poêle. Assaisonnez-la d'épices douces, cuisez-la vite et servez-la chaude. J'accorde aux nains le nom. Je ne leur accorde pas la méthode, qui implique beaucoup de cris." },
    [7755] = { "Le poisson-chat est un poisson de rivière, à large gueule et à moustaches, et généralement méprisé par ceux qui ne l'ont jamais bien cuisiné. Retirez la peau, toujours. La peau d'un poisson-chat a le goût du lit de la rivière, et le lit de la rivière n'est pas une saveur. La chair dessous est blanche et douce et se prête bien à une poêle chaude et à un retournement rapide. Les pêcheurs des rivières de Hautebrande ne jurent que par lui. Pour une fois, les pêcheurs et moi sommes d'accord." },
    [7827] = { "Le thon est un poisson pour ceux qui pensent qu'un poisson devrait se comporter comme une viande. Il est ferme, sombre et riche, et il prend une saisie franche à l'extérieur et très peu de cuisson au coeur. Les marins de Menethil le cuisent jusqu'à ce qu'il soit gris, puis accusent le poisson. Je ne vends aucune recette pour lui, mais je le ferais, et plus cher. Rose au coeur, c'est correct. Gris, c'est un aveu." },
    [7828] = { "La morue est le poisson des mers froides et des cuisines honnêtes, et la morue rochécaille est la meilleure de toutes, ainsi nommée parce que ses écailles émousseraient un mauvais couteau. Retirez-lui ses écailles avant toute autre chose, avec une bonne lame et de la patience. Puis une poêle chaude et un seul retournement. La chair est blanche et se défait en grands feuillets nets, et elle n'a besoin de rien, pas même d'un avis. Je lui en donne un quand même. Excellente." },
    [8238] = { "Les poissons déviants viennent des bassins empoisonnés des Cavernes des lamentations, dans les Tarides, et je n'ai jamais eu le moindre désir d'aller en chercher un. On trouve la recette dans le ventre des kodos qui errent là-bas, ce qui vous dit ce que les kodos en pensent. Cuisez-le à coeur, avec des épices douces, et mangez-le à vos risques. On me dit qu'il a des conséquences singulières pour ceux qui le mangent. On me dit beaucoup de choses sur les Tarides." },
    [8604] = { "Dans cette ville, tous les cuisiniers se croient capables de cuire un oeuf. La plupart se trompent, et toujours de la même façon : trop chaud, trop longtemps, et pressés d'en finir. C'est le premier plat que j'enseigne, et celui sur lequel je juge un cuisinier. Assaisonnez le blanc, jamais le jaune. Le jaune est déjà parfait et se passe très bien de votre avis. Tomas, à Comté-de-l’Or, en fait de tout à fait honorables. C'est moi qui le lui ai appris." },
    [8607] = { "Le fumage est l'art des nains, et je le dis sans plaisir. Au Loch Modan, ils suspendent la viande d'ours dans la fumée de leurs cheminées et l'y oublient tout l'hiver, et au printemps elle est meilleure que tout ce qu'ils avaient l'intention de cuisiner. Le secret, c'est la distance. La viande pend haut, là où la chaleur n'arrive jamais et où seule la fumée travaille. Près du feu, vous rôtissez mal. Loin du feu, vous fumez bien." },
    [9513] = { "Le thé de chardon est la boisson des voleurs de ce royaume, qui l'infusent avec du chardonnier et de l'eau de source et le boivent avant de faire ce que font les voleurs. Je ne demande rien. Infusez le chardonnier dans une eau tout juste retirée du feu jusqu'à ce qu'elle tourne au vert doré, puis filtrez. Le chardonnier trop infusé devient amer, ce que, me dit-on, les voleurs préfèrent. Je préfère savoir où se trouve ma bourse quand ils le boivent." },
    [13028] = { "La dorépine pousse dans les endroits durs, Strangleronce et les Hinterlands, et elle donne un thé que tout maître enseigne et que tout soldat emporte. Une dorépine donne quatre tasses, ce qui vous dit sa force. Infusez-la dans une eau tout juste retirée du feu jusqu'à ce qu'elle prenne la couleur du vieux laiton, puis filtrez fort. Une dorépine oubliée dans la tasse rend le thé assez amer pour décaper une peinture. Je l'ai vu faire. La peinture ne s'en est pas remise." },
    [15853] = { "Un steak tout simple, pris au flanc d'un loup, et la simplicité est la chose la plus difficile à cuisiner. Pas de sauce derrière laquelle se cacher, pas de ragoût pour y enterrer une erreur. Le flanc est maigre : il faut le saisir vite et le laisser reposer longtemps, avec un peu d'épices pour lui rappeler qu'il est un aliment. Saignant, c'est correct. Un peu plus cuit, c'est pardonnable. Au-delà, je vous suggère un autre métier, et j'en connais plusieurs qui se passent de feu." },
    [15855] = { "Le rôti de raptor est une nourriture de soldats, vendue dans les camps de Strangleronce, où les hommes mangent ce qui a tenté de les manger. Cela suffit à le respecter. La chair de raptor est maigre et vive, alors elle rôtit mieux en gros morceaux qui protègent leur propre coeur. Des épices fortes dehors, un feu vigoureux, puis à l'écart de la chaleur pour finir. Un raptor rôti comme un poulet en sort comme une botte. Un raptor rôti comme un raptor en sort comme une victoire." },
    [15856] = { "Les loups du grand sud sont rouges, mal lunés et plus grands que les nôtres, et leurs côtes viennent avec beaucoup de viande. Feralas vend cette recette à quiconque passe par là, ce qui n'arrive guère. Des épices fortes, un feu vif, puis de la patience, car le loup rouge est plus gras que nos loups gris et il lui faut du temps pour fondre. Quand la graisse coule claire et que les os foncent, c'est prêt. Quand la graisse fume, votre réputation aussi." },
    [15861] = { "Un ragoût de Strangleronce, fait par des soldats qui avaient de la viande de tigre, de l'eau de source et des pommes, et l'esprit de les réunir. Les pommes adoucissent ce qui serait sinon un bouillon dur et sauvage. Faites d'abord dorer le tigre, puis ajoutez l'eau et les pommes et laissez mijoter jusqu'à ce que le fruit ait disparu dans le ragoût. Une jungle produit beaucoup de nourriture et très peu de recettes. Celle-ci est l'une des bonnes." },
    [15863] = { "Tourte surprise. J'ai relu la recette deux fois, au cas où ce serait une plaisanterie. Ce n'en est pas une. De la viande mystère et des épices fortes, cuites en un plat que les trolls du Marais des Chagrins vendent comme s'il s'agissait d'une gentillesse. La viande doit être cuite à coeur, puis cuite à coeur de nouveau, car quoi qu'elle ait été, elle est morte depuis un moment. Je ne sers pas ce plat. Je l'enseigne, pour que mes élèves sachent ce qu'ils évitent." },
    [15865] = { "Le ragoût mystère, c'est de la viande mystère mijotée dans de la bière naine, et le mystère est de savoir laquelle des deux fait le plus de travail. Je vais vous le dire : la bière. Une outre de bonne bière naine rend la viande sombre et tendre et donne au bouillon une amertume qui cache une multitude de péchés. Daryl Riknussun l'enseigne à Forgefer comme un plat nain, ce qui est généreux de sa part, puisque les nains n'ont fourni que la bière et les questions. Faites-le cuire longtemps. Quoi que la viande ait été, elle doit l'oublier. Écumez la marmite pendant qu'elle mijote et ne la laissez jamais bouillir, sinon la bière tourne et la viande devient ficelle. Servi à Theramore et en Désolace à des gens qui ont cessé de poser des questions, il est, je l'avoue, très bon. J'ai cessé de poser des questions moi aussi. C'était plus facile que je ne le pensais." },
    [15906] = { "On me dit que ce plat est né d'un pari, dans une taverne où personne n'avoue avoir bu. Il a dépassé ses origines, comme moi. La plupart des cuisiniers en font un concours et le cuisinent comme une arme, ce qui en dit plus long sur eux que sur le chili. La viande mystère est un nom, pas une excuse. Parez-la comme si elle avait une réputation à perdre. Faites griller les épices avant que rien d'autre ne les touche, pour les réveiller. Le petit sac de flammes entre en dernier, percé une seule fois, et vous reculez. Vous comprendrez pourquoi le jour où vous vous tromperez. Bien fait, le feu arrive tard et repart lentement, comme un bon invité. Mal fait, il arrive le premier et reste toute la soirée, et les Veilleurs peuvent bien le garder." },
    [15910] = { "Les kodos de Désolace deviennent plus lourds que ceux des Tarides, nourris de rien du tout, et leur viande est la plus dense que je connaisse. Je n'ai nul besoin de goûter la cuisine de la Horde, et je fais une exception pour ce ragoût, parce qu'il tient moins de la Horde que du kodo, et le kodo n'y est pour rien. Deux portions de viande de kodo épaisse, des épices apaisantes et de l'eau de source, et toute une journée sur un feu doux. La viande entre froide et ressort en fils. Ne la pressez pas, et ne soulevez pas le couvercle toutes les heures pour voir comment elle va. Elle fait ce que fait le kodo : elle prend son temps. En Désolace, on vend cette recette en vue des ossements de kodos qui jonchent la vallée, ce qui me semble un peu indélicat, et parfaitement pratique." },
    [15915] = { "Le crabe au chili est un plat du sud brûlant, où les cuisiniers croient que l'épice est une forme d'hospitalité. De la viande de crabe tendre, beaucoup d'épices fortes et une poêle assez chaude pour vous faire reculer. Le crabe doit cuire dans l'épice, pas dessous, alors remuez sans cesse. C'est salissant à manger et impossible à manger poliment. Je le sers avec un avertissement et une grande serviette, et je garde la serviette." },
    [15933] = { "Une omelette monstrueuse se fait avec un seul oeuf géant, et un seul oeuf géant suffit à nourrir une table de six, ou un orc. Les oeufs viennent des grands oiseaux du nord, vendus en Gangrebois et au Berceau-de-l’Hiver par des gens qui ont appris à ne pas demander où on les a ramassés. Battez l'oeuf avec des épices apaisantes jusqu'à ce qu'il soit lisse et pâle, puis cuisez-le dans la plus large poêle que vous ayez, sur un feu modéré, en ramenant les bords à mesure qu'ils prennent. La tentation est de le presser, parce qu'il est grand et que les invités regardent. Résistez. Une omelette monstrueuse cuite vite est brune dehors et crue dedans, et personne ne le pardonne. Pliez-la quand le dessus a tout juste pris et laissez la chaleur finir le coeur pendant qu'elle va à table. Puis portez-la à deux mains, et savourez le silence." },
    [15935] = { "Cette recette vient de Tirisfal, où les cuisiniers sont morts et les chauves-souris pas encore. Elle m'est parvenue par un marchand en qui j'ai plus confiance qu'en sa marchandise. Je lui accorde ceci : une aile, c'est surtout de la peau, et la peau récompense le cuisinier qui sait la laisser tranquille. Posez-la sur une plaque brûlante, côté peau, et n'y touchez plus jusqu'à ce qu'elle se détache d'elle-même. Tout l'art est là. Le reste de la cuisine de Tirisfal, je le laisse à Tirisfal." },
    [18238] = { "Un jaune-queue des eaux chaudes au large de Tanaris, vendu par un gobelin qui pèse son poisson d'une main et le client de l'autre. Le poisson est excellent malgré tout. Il est ferme et gras et ne demande qu'une poêle chaude et un seul retournement. Ne vous agitez pas autour. Le jaune-queue tacheté est ce poisson rare qui est meilleur moins le cuisinier en fait, et beaucoup de cuisiniers trouvent cela insupportable." },
    [18239] = { "Un gros poisson luisant des eaux chaudes du sud, assez riche pour être servi en tranches épaisses. Les épices apaisantes lui conviennent, elles arrondissent sa richesse au lieu de la combattre. Saisissez les tranches fort et laissez-les reposer, comme une viande. Les marins de Baie-du-Butin le cuisent en grosses pièces sur du bois flotté et le mangent au couteau. Je l'ai vu. Je le revois encore, certaines nuits." },
    [18240] = { "Le calmar se cuit un instant ou une heure, et tout ce qui est entre les deux est du caoutchouc. Je préfère l'instant. Quadrillez le corps au couteau, frottez-y un peu d'épices apaisantes et posez-le sur le gril le plus chaud que vous ayez, le temps de dire son nom deux fois. Il se recourbe, il noircit sur les bords, il est cuit. Les cuisiniers du sud lui donnent une heure dans un ragoût. Ils ont tort, mais d'une manière intéressante." },
    [18241] = { "Le rouget est un poisson côtier, nommé pour la rougeur de ses ouïes, qui s'efface une fois pêché et cuit, comme la plupart des choses. Il n'a besoin de rien. Un filet, une poêle chaude, la peau en dessous jusqu'à ce qu'il se décolle tout seul. J'ai vu des cuisiniers attraper toutes les épices de l'étagère avec ce poisson, par nervosité. Un bon rouget n'est pas un problème à résoudre. C'est un poisson qu'on laisse tranquille." },
    [18242] = { "Fumer à chaud, c'est fumer à une chaleur qui cuit en même temps, plus vite que le fumage à froid et moins indulgent. Frottez la perche d'épices fortes, suspendez-la tout près au-dessus d'un feu fumeux et surveillez-la. Quand la chair passe du verre au blanc, c'est cuit. Une perche fumée ainsi se garde des jours et voyage bien. C'est le seul poisson que je confierais au sac d'un soldat, et je l'ai confié à plusieurs." },
    [18243] = { "Le nagenuit est un lutjan pêché après la tombée du jour, ce qui explique les horaires des pêcheurs et leur caractère. La soupe, c'est le poisson et de l'eau de source, rien d'autre, et c'est exactement assez. Faites frémir le lutjan doucement jusqu'à ce que la chair tombe des arêtes, puis retirez les arêtes. Le bouillon doit être assez clair pour qu'on lise au travers. S'il se trouble, vous l'avez fait bouillir. S'il est clair, vous pourrez me lire vos excuses plus tard." },
    [18244] = { "Pocher, c'est l'art de cuire dans une eau qui ne bout jamais tout à fait, et c'est l'art le plus sous-estimé de toute cuisine. Le saumon solécaille, des mers chaudes, est riche et tendre et se déferait sous une méthode plus rude. Amenez l'eau à frémir, pas à bouillir, descendez-y le poisson et laissez-le. Quand il devient opaque, sortez-le. L'eau ne doit jamais avoir élevé la voix." },
    [18245] = { "Du homard pince-noire, des côtes froides du nord, mijoté dans de l'eau de source et rien d'autre. Un homard n'a besoin d'aucune aide, seulement de respect. Portez l'eau au frémissement, descendez-y le homard entier et sortez-le à l'instant où sa carapace rougit. Puis retirez la chair de la carapace et remettez-la dans le bouillon pour la réchauffer. Un homard cuit deux fois est une insulte. Un homard réchauffé deux fois est un ragoût." },
    [18246] = { "Un grand barracuda est assez gros pour être découpé en steaks comme un taureau, et il doit être traité comme tel. Deux épices, fortes et apaisantes, l'une pour réveiller la chair, l'autre pour la calmer. Saisissez les steaks fort des deux côtés et laissez-les reposer avant de servir. Les pêcheurs du grand sud les remontent au filet avec force cris. Je les préfère dans une assiette, en silence, avec les applaudissements après." },
    [18247] = { "Du saumon blanchécaille des rivières froides, cuit entier au four avec des épices apaisantes, à chaleur modérée. Un poisson entier cuit de façon égale, là où un filet se dessèche sur les bords, et la peau protège la chair comme un couvercle. Quand l'oeil blanchit et que la nageoire se détache sans effort, c'est cuit. Feralas vend cette recette aux rares qui viennent jusque-là. Ils la méritent, ne serait-ce que pour le voyage." },
    [20626] = { "Une soupe gobeline, vendue en Tanaris par un gobelin nommé Jabbey, qui n'en garde qu'un exemplaire à la fois et apprécie la rareté plus que la soupe. La soupe vaut mieux que le gobelin. De la chair de palourde piquante, des épices fortes et du lait glacé, chauffés ensemble sans jamais bouillir. Les gobelins d'Undermine, dit-on, la mangent brûlante. Je recommande de la manger à une température qui ne réclame pas de guérisseur." },
    [20916] = { "Une truite à la tête argentée couleur de mithril, ce qui explique le nom, et d'un caractère assorti, ce qui explique les bandages des pêcheurs. C'est un poisson de montagne, au sang froid dans tous les sens du terme. Cuisez-la entière, avec la peau, dans une poêle chaude, et arrosez-la de sa propre graisse. La chair est pâle et fine. La tête reste en place pour la table. Une truite sans tête a l'air gênée, et le cuisinier qui l'a servie aussi." },
    [21143] = { "Un biscuit du Voile d'hiver, vendu quelques semaines par an par des marchands souriants vêtus de rouge, et fait par des enfants qui en mangent la moitié avant qu'il n'atteigne le four. Les épices spéciales en sont tout l'intérêt : chaudes, douces et vives, et elles doivent être fraîches, car l'épice éventée a le goût de l'an dernier. Un oeuf lie le tout. Faites cuire les biscuits jusqu'à ce que les bords foncent et que le coeur cède encore. Ils durcissent en refroidissant. Un biscuit cuit dur au four est une arme au matin." },
    [21144] = { "Le lait de poule est la boisson du Voile d'hiver, et la raison pour laquelle tant de matins du Voile d'hiver commencent tard. Un oeuf, du lait glacé, de l'eau-de-vie spéciale et des épices spéciales, battus ensemble jusqu'à ce que ce soit pâle et épais et que cela sente l'intérieur d'un bon buffet. L'eau-de-vie entre en dernier et avec modération, ce que personne n'a jamais réussi. Servez-le froid, dans de petites tasses, et ne remplissez pas les tasses de ceux qui ont commencé à chanter." },
    [21175] = { "De la viande d'araignée blanche, pressée en saucisse et enseignée par tous les maîtres cuisiniers du pays comme s'il s'agissait d'une chose ordinaire. Ce n'en est pas une. La chair d'araignée est douce et délicate, plus proche du crabe que du porc, et elle ne prend aucune épice parce qu'elle n'en a nul besoin. L'art est dans le boyau : assez ferme pour tenir, assez fin pour craquer dans la poêle. Beaucoup d'élèves pâlissent au mot araignée. Je leur demande s'ils ont déjà mangé du crabe, et j'attends." },
    [22480] = { "La viande de loup tendre vient des loups du Berceau-de-l’Hiver et des contrées froides, où une bête vit lentement et garde sa graisse. C'est la meilleure viande de loup du monde, et la plupart des cuisiniers la gâchent. Des épices apaisantes, une saisie brève et vive, puis laissez reposer aussi longtemps que vous avez cuit. Un cuisinier qui a gâché cent loups faméliques en Elwynn comprendra enfin, avec celui-ci, ce qu'il cherchait." },
    [22761] = { "La recette de ce plat est portée par un diablotin des ruines de Hache-tripes, qui ne s'en sépare qu'après avoir entraîné son poursuivant dans une course folle à travers des salles pleines de satyres très en colère. Je le sais parce qu'un de mes élèves a fait cette course et en est revenu avec la recette, une jambe qui boite et une opinion des diablotins que je partage. La racine de courante pousse dans l'ombre de ces ruines et a le goût, bien cuite, de la meilleure racine dont vous ignoriez l'existence : terreuse, douce et un peu fumée. Pelez-la, tranchez-la épais et rôtissez-la lentement avec des épices apaisantes jusqu'à ce que les bords caramélisent et que le coeur cède sous la fourchette. La surprise, c'est qu'une chose si bonne vienne d'un endroit si mauvais. J'enseigne la recette volontiers. Je n'enseigne pas la course, et j'ai conseillé à mon élève de ne jamais la refaire." },
    [24418] = { "Épais, dit-il, et ce n'est pas un mensonge : deux fois plus de crocilisque, avec des épices apaisantes, mijoté jusqu'à ce qu'une cuillère y tienne debout. Les soldats de Theramore le mangent dans des bols en fer-blanc sous la pluie d'Âprefange et jurent que c'est la seule chose chaude du marais. Je les crois. Un ragoût aussi épais doit être remué par le fond, souvent, sinon il attache et brûle là où vous ne le voyez pas. La plupart des ragoûts ratés meurent au fond de la marmite." },
    [24801] = { "Cette recette ne se vend pas. Elle s'enseigne, par les cuisiniers du Cercle cénarien en Silithus, à ceux qui ont fait leurs preuves dans un désert qui veut leur mort. Je ne suis jamais allé en Silithus. Je n'ai pas besoin d'y être allé pour savoir que la chair de ver des sables est un défi : dense, pâle et pleine de sable dans chaque repli. Lavez-la jusqu'à ce que l'eau soit claire, hachez-la fin avec des épices apaisantes et roulez-la en petites boulettes bien serrées, pour qu'elles tiennent dans la fumée. Puis fumez-les lentement sur un feu doux. La fumée parfume l'extérieur et la vapeur cuit le coeur, et quand elles sont prêtes, elles sont fermes, parfumées et entièrement débarrassées de leur sable, ce qui est le véritable exploit. Le Cercle garde jalousement cette recette, et je le respecte pour cela. J'ai gardé pire pour moins." },
    [25659] = { "Dirge Quikcleave tient une cuisine à Gadgetzan, en plein désert, où il cuit le chimaerok au carburant de fusée des gobelins et fait payer le privilège. J'ai toutes les raisons de mépriser cette recette. Je n'y parviens pas. Le filet de chimaerok est la meilleure viande de Kalimdor, dense et douce, tirée de bêtes si lointaines que seuls les braves ou les affamés en rapportent. Du sel de Fonderoc venu des mines des nains, des épices fortes, et le carburant, qui ne parfume pas la viande mais flatte le feu jusqu'à une chaleur qu'aucun charbon honnête n'atteint. Mettez beaucoup de distance et très peu de carburant. Dirge vous dirait le contraire. Dirge a moins de sourcils que moi. Les côtelettes en sortent noircies et juteuses et, je l'avoue, c'est ce qu'un gobelin a fait de mieux." },
    [25704] = { "Les sagerelles viennent des lacs de Hautebrande, où l'eau est froide et claire et les pêcheurs patients. Le poisson prend l'odeur de la sauge qui pousse sur les rives, d'où son nom, et un fumage doux fait ressortir cette odeur. Une fumée basse, une pincée d'épices et un après-midi. Les fermiers d'Austrivage la vendent à leurs fenêtres. C'est ce qu'il y a de mieux à Austrivage, ce qui n'est pas difficile, mais c'est noblement réussi." },
    [25954] = { "La grande sagerelle, c'est la sagerelle devenue adulte, avec davantage de tout, y compris l'odeur des herbes de son lac. Les épices fortes la font ressortir sans l'enterrer. Saisissez le filet côté peau jusqu'à ce que la peau croustille, puis retournez-le un instant, pas plus. Délice est un mot fort pour un poisson. J'ai goûté celui-ci, et je ne le retire pas. Je le sers à ceux qui prétendent ne pas aimer le poisson, et je les regarde changer d'avis sans le dire." },
    [470359] = { "Une bisque de homard pince-noire faite avec de l'eau sacrée de Stratholme, qu'on me dit potable, même si j'ai lu l'étiquette deux fois et que je ne suis toujours pas convaincu. L'expédition de Silithus la vend, et je soupçonne qu'elle l'a inventée pour écouler l'eau sacrée. Cela fonctionne. L'eau est très propre et très douce, et elle laisse le homard parler de lui-même. Faites frémir, tamisez, et ne demandez pas à quoi d'autre cette eau a servi." },
    [470370] = { "Une recette vendue en Silithus par les intendants de l'expédition, à des soldats qui avaient besoin d'une nourriture qui tienne dans le sable. Du rouget, fumé lentement jusqu'à être assez sec pour voyager et encore assez tendre pour être mangé. Pas d'épices, seulement la fumée. Les soldats qui l'ont rapporté à Hurlevent m'ont demandé de l'approuver. Je l'ai fait, ce qui les a plus surpris que le désert." },
    [1225758] = { "Le steak de rôdeur, c'est du tigre, ce que le nom est trop poli pour dire. Deux morceaux, frottés de sels sacrés et laissés une heure avant que le feu ne les touche. Le tigre est une viande maigre et travailleuse, et le sel l'apprivoise. Le reste est retenue : un fer brûlant, une saisie brève et un long repos. J'ai entendu des chasseurs soutenir qu'un tigre doit être cuisiné en colère. Les chasseurs devraient chasser, et laisser la cuisine à ceux qui savent compter jusqu'à soixante." },
    [1225759] = { "Filet de flanc, un nom qui sonne comme une hésitation de boucher, et un plat où rien ne manque. Le flanc de loup rouge est frotté de sels sacrés, dont le clergé vous dira qu'ils sont bénis et les marchands qu'ils sont chers. Les deux ont raison. Le sel tire l'eau de la viande et la raffermit, alors cuisez-la vite. Un steak béni trop cuit reste trop cuit. La Lumière ne le sauvera pas, et moi non plus." },
    [1225760] = { "Une omelette de deux oeufs géants assaisonnée de sels sacrés, que quelqu'un a décidé d'appeler un lever de soleil. Je suppose que c'est la couleur : un jaune très vif, un blanc pâle, et une pincée de sel que le clergé a béni et que les marchands ont tarifé en conséquence. Cuisez-la lentement, pour que la couleur reste vive. Un lever de soleil cuit trop vite devient midi, et personne n'écrit de poèmes sur midi. Je la sers aux prêtres, qui apprécient la plaisanterie, et aux paladins, qui ne l'apprécient pas." },
    [1225762] = { "Le festin de loche est le banquet d'un cuisinier qui avait beaucoup de poisson et l'ambition d'un seul raptor. Douze jaune-queues tachetés, trois morues rochécaille et quatre portions de raptor, avec des épices exquises, qui méritent leur nom au comptoir, sinon toujours dans la poêle. Les poissons sont grillés entiers et le raptor rôti, et l'astuce, comme pour tout festin, est que tout arrive en même temps. Grillez d'abord les morues, parce qu'elles sont plus épaisses, et les jaune-queues en dernier, parce qu'ils sont rapides. Le raptor repose pendant que les poissons cuisent, ce qui arrange tout le monde. Disposez le tout sur la plus grande planche que vous ayez, le raptor au milieu comme un général et les poissons autour en rangs. Un festin est une représentation. Le public la mange. En cuisine, on salue ensuite et l'on mange ce qui reste, c'est-à-dire en général la morue." },
    [1225763] = { "Un banquet n'est pas un plat. C'est une campagne. Douze homards pince-noire, quatre portions de tortue, trois ailes de busard et une bourse d'épices exquises, ainsi nommées parce que le marchand qui les vend a besoin d'un mot pour le prix. Les homards sont pochés, la tortue mijotée, le busard rôti, et le tout porté à table en même temps, ce qui est la véritable difficulté. Chaque partie doit finir au même instant, alors commencez par la plus lente, la tortue, et finissez par la plus rapide, les homards, sortis dès qu'ils rougissent. J'ai cuisiné un banquet de ce genre pour la noblesse de Hurlevent, et voici ce que j'en ai appris : les invités se souviennent du homard, et le cuisinier se souvient du minutage. Personne ne se souvient du busard. Cuisez-le bien quand même. Quelqu'un remarque toujours ce que vous avez négligé." },
    [1229737] = { "Avant le plat, il y a le feu, et avant le feu, il y a un cuisinier qui sait le faire. Du bois simple, empilé sans serrer pour que l'air puisse circuler, allumé par le bas et laissé tranquille. Un cuisinier qui ne sait pas faire un feu est un invité. Un cuisinier qui en fait un rugissant est un fanfaron. Le bon feu pour cuisiner est celui qui a cessé de vouloir vous impressionner et s'est installé en braises." },
    [1247741] = { "Un poisson que je n'ai pas encore vu au marché de Hurlevent, même si les pêcheurs en parlent comme ils parlent de tous les poissons qu'ils n'ont pas pris. Le flétan est un poisson large, blanc et généreux, et celui-ci, armé d'épines, se défend, me dit-on, au bout de la ligne comme en cuisine. Cuisez-le en morceau épais, doucement, jusqu'à ce que les feuillets se séparent tout juste sous le doigt. Le flétan trop cuit, c'est de la craie. Quand on m'en apportera un, j'en dirai davantage, et je le dirai le premier." },
    [1249957] = { "Le pacifique est cette fleur pâle qui pousse au bord de toutes les routes, et les trolls Frostmane de Dun Morogh, me dit-on, en font ce thé avant d'attaquer nos nains. Je trouve cela étrangement rassurant. Deux fleurs de pacifique pour une mesure d'eau de source, portée juste sous l'ébullition et laissée infuser jusqu'à prendre la couleur de la paille. Faites-la bouillir et elle aura le goût du foin. Laissez-la infuser et elle aura le goût d'un après-midi tranquille. Les trolls, de toute évidence, n'en ont jamais bu." },
    [1249958] = { "Le mage royal est une herbe qui a une haute opinion d'elle-même, et le thé royal est du mage royal infusé dans du lait glacé, ce qui donne aussi au lait une haute opinion de lui-même. On chauffe doucement le lait et on y laisse l'herbe jusqu'à ce qu'il prenne une teinte violette pâle et l'odeur d'un beau jardin. Ne le faites pas bouillir. Le lait bouilli forme une peau, et une peau sur un thé royal est une couronne de paysan. Je le sers aux nobles, qui goûtent l'ironie moins que moi." },
    [1249959] = { "De la vietérule infusée dans du jus de melon, ce qui est une drôle de façon de faire du thé, et une bonne. On chauffe le jus de melon jusqu'à ce qu'il fume tout juste, et on y laisse la vietérule, lavée et tranchée, jusqu'à ce que le jus fonce et sente à la fois la terre et l'été. Filtrez avec soin. Une racine laissée trop longtemps donne au thé le goût de la terre où elle a poussé, et la terre n'était pas invitée. Les murlocs de Hautebrande portent cette recette, ce que je prends pour la preuve que même les murlocs ont des après-midi." },
    [1249960] = { "Un thé pour après le combat, je le devine au nom, fait de nectar sucré et de pâlerette. La pâlerette est l'herbe que les voleurs mâchent pour passer inaperçus, ce qui me semble une curieuse chose à donner aux blessés. Chauffez le nectar jusqu'à ce qu'il fume, faites-y infuser la pâlerette et filtrez avant qu'elle ne devienne amère. Je n'ai pas encore vu cette recette en vente. Quand je la verrai, je l'achèterai, et j'offrirai à boire au guérisseur qui l'a écrite." },
    [1249961] = { "De la soleillette infusée dans du jus de baie lunaire, ce qui est une plaisanterie sur le soleil et la lune que la recette ne prend pas la peine d'expliquer. On chauffe le jus et on y laisse la soleillette jusqu'à ce que la boisson devienne dorée et sente le foin l'après-midi. Filtrez et servez tiède. C'est une boisson gaie, ce qui est rare, et je n'ai rien de cinglant à en dire, ce qui l'est plus encore." },
    [1249962] = { "De la sauge-argent des montagnes infusée dans de la rosée matinale, c'est-à-dire un thé fait entièrement de choses difficiles à trouver. C'est pour cela, je le soupçonne, qu'on l'appelle le thé des sages. Chauffez doucement la rosée, laissez-y infuser la sauge-argent jusqu'à ce que la boisson soit pâle et sente l'air froid et la pierre, puis filtrez. C'est un très bon thé. C'est aussi une façon coûteuse de se sentir sage, qui est la plus répandue." },
    [1249963] = { "Un frappé fait avec une glande à venin, que le vendeur m'a assuré sans danger, avec l'aplomb d'un homme qui n'en avait pas encore bu. De l'eau de source, des épices douces et la petite glande à venin, écrasée et filtrée pour qu'il n'en reste que le piquant et non l'intention. Secouez fort et buvez-le froid. Il mord la langue en descendant, ce qui, je crois, est tout le but. Je ne vends rien de tel. Je le pourrais un jour, si le vendeur survit." },
    [1249964] = { "Gélatineux, dit-il de lui-même, et c'est le nom le plus exact de ce chapitre. Du lait glacé, des épices douces et de l'ichor d'araignée, secoués jusqu'à ce que l'ichor cesse de bouder au fond du verre et accepte d'être une boisson. Servez-le aussitôt, parce qu'il ne reste pas conciliant. Je ne l'aurais pas inventé. J'ai cependant vu un gnome en boire trois, ce qui en dit plus long sur les gnomes que sur le frappé." },
    [1249965] = { "Je n'essaierai pas de prononcer le nom de cette boisson. J'ai entendu un murloc essayer, et cela ne s'est bien passé ni pour lui ni pour moi. Du jus de melon, des épices fortes et un aileron de murloc, secoués ensemble jusqu'à ce que l'aileron cède son corps au jus. C'est sucré, puis brûlant, puis quelque chose que je ne peux appeler que côtier. Les murlocs, je le soupçonne, le boivent pour insulter le reste du monde. C'est, je l'avoue, une insulte bien faite." },
    [1249966] = { "Un frappé avec un croc dedans. J'ai lu la recette deux fois, puis une troisième avec mes lunettes. Du nectar sucré et des épices fortes, et un grand croc moulu en poudre fine et mêlé au tout, ce qui donne à la boisson un corps crayeux et, me dit-on, en fait la favorite des gens qui combattent les ours. Filtrez bien. Une boisson qui crisse sous la dent est une boisson qui appelle une réclamation, et je n'accepte pas les réclamations." },
    [1249967] = { "Du jus de baie lunaire, des épices apaisantes et un petit sac de flammes, percé et pressé dans le verre. Les épices apaisantes sont là, je le soupçonne, pour s'excuser du sac de flammes. Secouez fort et buvez vite, avant que la chaleur ne se décide. C'est la seule boisson que je connaisse qui réchauffe les mains de l'intérieur. Les mages de feu du quartier des Mages la commandent au pichet, ce qui vous dit tout ce qu'il faut savoir des mages de feu." },
    [1249968] = { "De la rosée matinale, beaucoup d'épices apaisantes et une serre cruelle, moulue fin. Pernicieux est le mot juste. La serre donne à la boisson une arête sombre et amère que les épices passent toute leur vie à tenter d'adoucir, sans jamais y parvenir tout à fait. Secouez-le froid. Je ne sais pas qui boit cela par plaisir. Je sais qui le boit par défi, et j'en ai mis plusieurs à la porte de ma cuisine." },
    [1250142] = { "Des mini-burgers, me dit-on, c'est petit et nombreux, comme les jeunes cuisiniers aiment toute chose. Le cerf est haché fin avec des épices fortes et pressé en galettes de la taille d'une paume. Pressez-les une fois et plus jamais : une galette pressée deux fois donne son jus à la poêle au lieu de l'invité. Je n'approuve pas la nourriture conçue pour être mangée debout. J'approuve celle-ci, debout, et je n'en suis pas fier." },
    [1250143] = { "Une pamplona, c'est de la viande aplatie, farcie et roulée, et celle-ci est faite de busard, la seule chose qui plane dans ce plat. Trois ailes, désossées et aplaties, roulées autour d'épices apaisantes et ficelées. C'est un travail minutieux, et c'est dans le travail minutieux qu'on éprouve un cuisinier. Roulez serré, rôtissez doucement et tranchez en rondelles. Les rondelles montrent votre travail au couteau. Veillez à ce qu'elles montrent quelque chose que vous signeriez." },
    [1250144] = { "Le hachis est un vieux mot de ferme pour un ragoût lent de viande hachée, et ici, la viande est de la chauve-souris. Je n'aurais pas choisi la chauve-souris. La chauve-souris ne m'aurait pas choisi non plus. Trois ailes, hachées, avec des épices apaisantes, et un feu doux pendant presque toute une soirée, jusqu'à ce que les tendons fondent en quelque chose qu'on peut servir à un invité. Celui qui l'a inventé était pauvre et malin. Je respecte les malins, et j'ai appris, avec les années, à pardonner aux pauvres." },
    [1250145] = { "De la tortue mijotée plutôt que tamisée, ce qui en fait un plat de paysan, et il ne s'en porte pas plus mal. Trois portions de tortue et une main généreuse d'épices apaisantes, mijotées jusqu'à ce que la viande se défasse. Ne la tamisez pas. La texture est tout l'intérêt d'un ragoût, et un ragoût de tortue a beaucoup de texture, en partie volontaire. Servez-le épais, dans des bols, sans vous excuser d'être honnête." },
    [1250146] = { "Au poivre, dit le nom, et il n'y a pas de poivre dedans. Il y a du flanchet de loup rouge et des épices apaisantes, et les épices font le travail du poivre assez bien pour que personne ne s'en plaigne. Saisissez le flanchet fort, laissez-le reposer pendant que la poêle refroidit, et reversez le jus par-dessus. Ne le découpez jamais sur la planche où il a été saisi. La planche se souvient de la chaleur, et la viande aussi." },
    [1250147] = { "Bruscitt. J'ai cherché ce mot dans trois langues sans le trouver dans aucune. Le plat est assez simple pour s'expliquer tout seul : de la viande de grand ours tranchée fin, en couches avec des épices apaisantes, rôtie lentement jusqu'à ce que les couches se soudent. L'astuce est de trancher à froid, car la viande tiède se déchire sous le couteau. Celui qui a nommé ce plat voulait faire étranger. Le plat, lui, n'a rien à cacher, et je l'aime mieux que son nom." },
    [1250148] = { "Un steak de cerf servi fumant, c'est-à-dire servi aussitôt, comme tout steak devrait l'être et comme presque aucun ne l'est. Trois morceaux de cerf, des épices apaisantes bien frottées, un fer très chaud. La vapeur est tout l'enjeu. S'il arrive à table sans vapeur, il a attendu là où il n'aurait pas dû, et quelqu'un dans votre cuisine vous doit des excuses, et très probablement un autre steak." },
    [1250149] = { "Un nom de chasseur pour un plat de cuisinier, comme si le tigre avait été pris par la foudre. Le tigre a été pris par un chasseur et beaucoup d'attente. Le steak, en revanche, mérite son nom : trois morceaux de tigre, des épices apaisantes et le feu le plus vif que vous puissiez faire, le temps le plus court que vous puissiez supporter. Frappez vite, laissez reposer longtemps. C'est dans la seconde moitié que la plupart des cuisiniers perdent leurs nerfs." },
    [1250150] = { "Une recette dont j'ai entendu parler sans jamais la voir vendue, ce qui est la plus dangereuse espèce. Le raptor a depuis longtemps cessé de bouillir quand il arrive dans la poêle, donc le nom parle des épices, et il y en a beaucoup. Cuisez les côtelettes à feu doux jusqu'à ce que la viande se détache de l'os, puis sur un feu féroce pour saisir la croûte. Ne les servez qu'à ceux qui les ont demandées. Je ne dis pas cela de tous les plats." },
    [1250151] = { "La poitrine est le morceau d'un cuisinier patient, et la poitrine d'ours celui d'un saint. C'est la partie la plus dure de l'animal, tout en travail et en vieux muscle. Frottez-la d'épices fortes et donnez-lui le plus petit feu que vous puissiez entretenir, et une journée entière. Quelque part dans la soirée, elle rend les armes et se défait sous la fourchette. Je ne peux pas vous dire l'heure. Je peux vous dire que le cuisinier qui vérifie trop souvent n'y arrive jamais." },
    [1250152] = { "Préhistorique, comme si le raptor attendait depuis le commencement du monde d'être effiloché à deux fourchettes. Peut-être était-ce le cas. Trois portions de raptor et beaucoup d'épices apaisantes, puis le plus petit feu que vous puissiez entretenir pendant presque toute une journée. La viande est prête quand elle se défait au moindre contact. Effilochez-la à la fourchette, jamais au couteau. Au couteau, c'est du raptor tranché, et le raptor tranché est un autre chapitre, et un moindre." },
    [1250153] = { "Paupiette : un mot de cuisine savante pour une chose simple, de la viande roulée. De fines tranches de raptor roulées autour d'épices fortes et ficelées. La viande roulée cuit de l'extérieur vers l'intérieur, alors le dernier tour doit être fin, sinon le coeur reste cru. Dorez les rouleaux sur toutes les faces, puis baissez le feu et laissez-les tranquilles. Quand la ficelle noircit, retirez-la. Si vous servez la ficelle à un invité, vous méritez le regard qu'il vous lance." },
    [1250154] = { "Deux fois épicé, et pour une fois un plat dit la vérité sur lui-même. Le raptor est frotté une fois avant d'être tranché et une fois après la cuisson, et la seconde fois n'est pas pour le goût mais pour la croûte. La chair de raptor est maigre et sèche vite. Tranchez-la contre le fil, assez fin pour voir une bougie au travers, et donnez-lui le feu le temps d'un souffle, pas plus. Une recette que je n'ai pas inventée, et que j'aurais inventée, avec le temps." },
    [1250155] = { "Les oeufs brouillés sont la première épreuve de la patience d'un cuisinier, et les oeufs brouillés géants sont la même épreuve dans une plus grande poêle. Deux oeufs géants et des épices fortes, battus ensemble et remués sur un feu doux, lentement, sans cesse, jusqu'à ce qu'ils prennent en grumeaux tendres. Une poêle chaude en fait du caoutchouc. Une poêle douce en fait de la soie. La plupart des cuisiniers ne supportent pas de remuer si longtemps. La plupart des cuisiniers ne devraient pas approcher un oeuf géant." },
    [1250156] = { "Une recette qu'on trouve dans les nids de raptors, ce qui est soit une plaisanterie, soit un avertissement. Les bouchées se font avec l'oeuf, pas avec la bête, et un oeuf de raptor est une chose plus lourde et plus riche que tout ce qu'une poule a jamais pondu. Assaisonnez-le plus généreusement que la décence ne le voudrait, car le jaune boit chaque grain. Cuisez les bouchées petites et vite. Un oeuf de raptor cuit lentement devient caoutchouc par pure rancune. Je soupçonne la mère de le lui avoir appris." },
    [1250157] = { "Une omelette de petit déjeuner, avec un oeuf et une quantité franchement alarmante d'épices douces. Celui qui a écrit cette recette s'est réveillé affamé et en colère. Le secret de toute omelette tient à la chaleur et à la vitesse : une poêle chaude, l'oeuf battu jusqu'à n'avoir qu'une couleur, et une fourchette qui ramène les bords à mesure qu'ils prennent. Pliez-la tant que le coeur est encore baveux. La recette a été trouvée dans les Carmines, dans le nid d'un condor, ce qui explique la colère, sinon les épices." },
    [1250158] = { "Des linguines, me dit-on, ce sont de longues pâtes plates d'une cuisine lointaine. Il n'y a pas de pâtes dans la recette. Il y a de la chair de palourde piquante, en grande quantité, taillée en longs rubans et enrobée d'épices apaisantes, d'où vient le nom, je suppose. Cuisez les rubans un instant dans une poêle chaude et servez aussitôt. Ils s'emmêlent comme des pâtes et se mangent comme des palourdes. J'approuve la supercherie." },
    [1252566] = { "Fantaileron. Quelqu'un a donné ce nom à un poisson, et quelqu'un d'autre a été d'accord. La recette apparaît dans les Carmines, dans les sacs des gnolls et des murlocs, qui ne sont pas réputés pour leur cuisine, alors je suppose qu'ils l'ont volée à quelqu'un qui l'était. Le poisson est petit, vif et délicat. Une pincée d'épices douces, une poêle chaude, très peu de temps. Le nom promet de la fantaisie. Le plat livre un souper, ce qui vaut mieux." },
    [1255241] = { "Un ragoût fait d'une fleur gangrenée que quelqu'un a purifiée, ce qui, m'assure-t-on, en refait une herbe et non plus une menace. Je crois les druides sur parole en pareille matière, et sur très peu d'autres. La viande de cerf et un oeuf géant lui donnent du corps, l'oeuf battu à la fin pour que le bouillon devienne soyeux. On le prépare, me dit-on, pour ceux qui reviennent de Gangrebois, et ils méritent une cuisine plus aimable que la forêt qu'ils ont quittée." },
    [1262978] = { "Macaron est le murloc qui tient la cuisine de la Confrérie défias, au fond des Mortemines, et l'on me dit qu'il cuisine une louche dans une main et un couperet dans l'autre, sans trop se soucier de celui qu'il utilise sur les visiteurs. Sa recette a été rapportée de la mine par des aventuriers qui la lui ont prise, et je l'ai étudiée avec un intérêt professionnel dont je ne suis pas fier. Deux portions de viande mystère et une de kodo épais, rôties lentement avec des épices apaisantes jusqu'à ce que le kodo s'attendrisse et que le mystère s'épaississe. C'est un festin, c'est-à-dire qu'il se partage sur un plat commun, ce que je trouve peu hygiénique et que les Défias, sans doute, trouvent nécessaire. Le plat est excellent. Le cuisinier est un murloc et un criminel. Je l'engagerais demain, s'il laissait son couperet à la porte." },
    [1263067] = { "Un four en fer, dit la recette, puis elle demande de la farine, de l'eau de source et des épices apaisantes, et pas un gramme de fer. Je l'ai relue plusieurs fois. Je crois que le four est le récipient, et la recette ce qu'on y met d'abord, une grande quantité de pâte travaillée avec les épices et cuite pour culotter le fer, comme on culotte une poêle neuve. Quel que soit son secret, c'est une recette de maître, et je ne la possède pas encore, ce qui m'agace plus que je ne puis le dire poliment." },
    [1270632] = { "Un biscuit fait pour les petits animaux qui suivent les aventuriers partout, et fait, je le note, de rien d'autre que de farine, ce qui vous dit à quel point on consulte les petits animaux. Cinq mesures de farine, travaillées d'une main légère et cuites jusqu'à un or pâle. On me dit que les bestioles les adorent. J'ai vu un chat en manger un. Le chat m'a regardé ensuite comme s'il en attendait davantage, ce qui est la seule critique qu'un animal de compagnie ait jamais rendue." },
    [1270633] = { "Un soufflé, c'est un oeuf qu'on a convaincu de se tenir debout, et le soufflé de Mur-Céleste, nommé pour quelque hauteur que je n'ai pas visitée, se tient plus haut que la plupart. Deux oeufs et un peu de farine, les blancs montés jusqu'à former un bec, incorporés doucement et cuits sans jamais ouvrir la porte du four. C'est la règle. Ouvrez la porte et il retombe, et il ne remontera plus ni pour vous ni pour personne. Le soufflé est le seul plat qui boude pour toujours." },
    [1270635] = { "La saison des crabes, appelle-t-on la tâche qui enseigne ce plat, comme si les crabes avaient des saisons et n'étaient pas simplement toujours là, à trottiner au bord de chaque plage. On casse les pinces, on en tire la chair, on la lie avec un peu de farine et on la frit en petites bouchées. Mettez le moins de farine possible. Elle tient le crabe ensemble. Elle ne doit pas devenir le plat. Une bouchée qui a le goût du pain vous a menti sur la plage." },
    [1283400] = { "Le bois d'étoile brûle plus chaud et plus proprement que le bois commun, et un cuisinier compagnon devrait connaître la différence avant qu'on le laisse approcher d'un meilleur feu. La recette a été trouvée dans les Cavernes des Lamentations, parmi les druides qui s'y sont égarés, ce qui fait beaucoup de chemin pour un meilleur feu de camp. Empilez-le de la même façon, sans serrer, et laissez-le retomber plus bas avant de cuisiner. Un feu plus chaud pardonne moins. C'est ce que signifie être compagnon." },
    [1291341] = { "Des bûches épaisses, qui mettent une éternité à prendre puis brûlent toute une soirée, régulières comme un âtre. C'est le feu d'un spécialiste, et il enseigne une leçon de spécialiste : la longue chaleur égale vaut l'attente. Disposez les bûches en carré, laissez un passage pour l'air, allumez le petit bois dessous et prenez patience avec lui. Je n'ai pas encore vu cette recette en vente. J'ai vu des cuisiniers qui croyaient ne pas en avoir besoin, et ils n'ont jamais tout à fait été des spécialistes." },
    [1294014] = { "Une confiture des baies d'Hyjal, qui poussent sur les pentes d'une montagne qu'on me dit sacrée et que je crois surtout très froide. Trois mesures de baies et des épices apaisantes, réduites lentement jusqu'à ce qu'une goutte sur une assiette froide se ride quand on la pousse. C'est votre épreuve. Trop liquide, vous avez fait une sauce. Trop ferme, vous avez fait une brique. Patte-douce, l'appelle-t-on, pour les ours qui pillent les buissons. Les ours ont raison sur les baies." },
    [1295805] = { "Un ragoût du rivage, fait de ce que le rivage offre, c'est-à-dire du crabe et, à mon éternel regret, des yeux de murloc. Les yeux donnent du corps au bouillon, comme dans le ragoût de la Marche de l'Ouest, et j'ai appris à cesser de discuter avec eux. La viande de crabe tendre entre à la fin, pour rester douce. Des épices fortes tout du long. Le résultat est saumâtre et riche et sent la mer avant qu'on l'ait nettoyée." },
    [1295834] = { "Une recette des Rives Claires, vendue par une femme qui n'a vu aucune raison de lui donner un nom plus grandiose, et elle avait raison. De la viande de sanglier, en bonne quantité, avec une pincée d'épices douces, rôtie sur l'os jusqu'à ce que la graisse crépite. C'est tout. J'ai passé ma vie à apprendre aux cuisiniers à ne pas en faire plus, et voici une fermière qui n'a jamais eu besoin de leçon. Laissez reposer avant de découper. La cuisine simple ne pardonne rien, et c'est pourquoi elle est si rarement bien faite." },
    [1319313] = { "Un poisson qui porte une armure, ce qui semble juste, vu ce qui arrive à ceux qui n'en portent pas. Les plaques s'enlèvent avec un couteau lourd et un peu de patience, et la chair dessous est ferme et pâle, comme une queue de homard. Des épices apaisantes, une chaleur modérée, et ne le pressez pas. Les poissons cuirassés prennent leur temps pour cuire et pour quitter leur carapace. Faites de même." },
  },
  eunice = {
    [2538] = { "Le premier plat de tout cuisinier, vivant ou non. On l'apprend sur la route avec un couteau et un feu, parce qu'il y a toujours un loup et toujours quelqu'un qui a faim. Prêtez l'oreille. La viande de loup siffle quand elle rencontre la chaleur et se tait quand l'extérieur est saisi. Retournez-la une fois, au silence. Mes élèves veulent la piquer. Je les laisse faire, une fois, puis je les laisse manger ce qu'ils ont piqué." },
    [2539] = { "Je l'enseigne le deuxième jour, après le loup grillé, pour que mes élèves apprennent que l'épice n'est pas une correction. Frottez-la dans la viande avant le feu. Ajoutée à la fin, elle sent l'épice et le loup, deux étrangers à la même table qui ne se parlent pas. Ajoutée au début, elle sent le souper. Les vivants me disent que la différence est tout aussi nette sur la langue." },
    [2540] = { "En Lordaeron, on rôtissait le sanglier à la moisson, dans une fosse derrière la grange, ou derrière l'auberge, ou derrière la grange de quelqu'un. Je me souviens nettement de la fosse et pas du tout de la grange. Ici, c'est un plat simple pour les jours simples. Rôtissez la viande en morceaux, jamais entière : un sanglier entier prend la journée, et ceux qui l'attendent ne vous la donneront pas. Quand la graisse commence à sentir le sucré plutôt que l'âcre, c'est prêt." },
    [2541] = { "Les coyotes mangent tout ce que le monde laisse tomber, et leur viande se souvient de chaque repas. Elle ne prend pas d'épices, seulement une poêle chaude et un cuisinier qui ne s'en excuse pas. Saisissez-la jusqu'à ce que les bords se recourbent et que l'odeur passe du sang à la noisette grillée, puis retirez-la du feu et n'y touchez plus. Un steak de coyote n'est jamais tendre, me disent les vivants en mâchant. Il est honnête, et la nourriture honnête tient un voyageur debout sur une longue route." },
    [2542] = { "Une tourte de ferme du sud, et nous en faisions une toute pareille en Lordaeron, avec du foie de porc, ou de veau, les jours où le boucher était passé. Je revois le plat à tourte. Il était bleu, avec un éclat sur le bord, et il refroidissait sur le rebord d'une fenêtre, et je ne sais pas de quelle fenêtre il s'agissait. Le foie de Broche-tripes est fort et sombre. Faites-le tremper dans l'eau froide avant de le cuire, pour en tirer l'amertume, puis assaisonnez-le d'épices douces et donnez-lui un four doux. Le foie cuit vite sent le fer et devient gris. Le foie cuit lentement sent quelque chose de riche et de doux, comme la terre tiède après la pluie, et c'est là qu'il est prêt. Mes élèves la préparent pour les vivants de passage, et les vivants la mangent comme si elle leur était familière. Peut-être l'est-elle, pour eux." },
    [2543] = { "Un ragoût de fermier du sud, fait de ce que la terre donne quand elle donne très peu : du vautour, le groin d'un Broche-tripes et un oeil de murloc, dont je ne m'excuserai pas. Nous avions un ragoût de ce genre en Lordaeron, fait de ce que les champs et la rivière voulaient bien laisser. Je me souviens de la marmite. Je me souviens qu'elle était noire et lourde, et que quelqu'un se brûlait toujours la main avec. La main de qui, je ne saurais plus le dire. L'oeil donne du corps au bouillon, alors ne l'enlevez pas pour épargner un invité délicat. Les invités délicats peuvent bien jeûner. Laissez mijoter jusqu'à ce que le vautour renonce, ce qui prend plus longtemps que vous ne le croyez. Les voyageurs du sud me disent que les fermes y sont vides maintenant. Le ragoût a survécu aux fermes, comme les ragoûts savent le faire." },
    [2544] = { "Austrivage faisait des beignets de crabe à chaque fête, ou une fête sur deux, et les femmes se disputaient sur l'épice par la fenêtre de l'auberge, ou de la boulangerie. Je me souviens mieux des disputes que des beignets. Nettoyez bien la chair de clampant, ajoutez une pincée d'épices douces et pressez le tout à la main. Faites-le frire jusqu'à ce que l'extérieur prenne. S'il s'effondre, pressez plus fort la prochaine fois. S'il rebondit, pressez moins. La dispute est facultative." },
    [2545] = { "Fendez la pince avant qu'elle ne rencontre le feu, pour que la chaleur atteigne la chair au lieu de la cuire à la vapeur dans sa propre carapace. Une pincée d'épices douces dans la fente. Un feu bref et chaud. Vous entendrez la chair grésiller dans la carapace, un petit bruit affairé, et quand il s'arrête, la pince est cuite. Tirez la chair à la fourchette. La carapace va aux apothicaires, qui veulent tout." },
    [2546] = { "Pas de sauce, seulement des épices, un feu doux et un après-midi entier, comme les fermes les cuisaient à la fin de la moisson, ou au début, je ne sais plus. Les côtes sont prêtes quand les os dépassent d'un doigt aux extrémités et que l'odeur est passée de la viande à quelque chose de plus proche du pain grillé. Je les sers sur du papier, à des gens qui mangent avec les doigts et se moquent qu'on les voie. Ici, à Fossoyeuse, c'est presque tout le monde." },
    [2547] = { "De l'araignée et du condor, mijotés ensemble. Le condor est coriace et l'araignée ne l'est pas, alors le condor entre d'abord et l'araignée bien plus tard. Mettez-les ensemble et vous sentirez l'araignée trop cuire, une note aigre et piquante, bien avant que le condor soit près d'être prêt. C'est un plat du sud, de gens qui avaient plus d'araignées qu'ils n'en voulaient. Je comprends très bien ces gens-là." },
    [2548] = { "Deux portions de côtes et des épices fortes, retournées toutes les quelques minutes pour que la graisse arrose la viande en fondant. Retourner, c'est la recette. Une côte laissée à elle-même brûle dessous et boude dessus. Une côte souvent retournée en sort brillante et généreuse. Un fermier m'a appris cela, un voisin, je crois, avec une barbe rousse, ou une grange rouge. Je donne celui-ci aux élèves qui croient que cuisiner, c'est attendre. Ce n'est pas le cas. C'est faire attention pendant qu'on attend." },
    [2549] = { "Herbes aromatiques de Stormwind, dit le sachet, et elles sentent exactement comme je me souviens du marché de l'ancienne capitale, c'est-à-dire que je ne saurais vous dire si ce souvenir est celui de Hurlevent, de Lordaeron ou d'un rêve. Le loup s'en moque. Enfilez la viande en laissant de l'espace entre les morceaux, pour que la chaleur atteigne chaque face, et guettez la graisse qui crache. Quand elle cesse de cracher et se met à chanter, retournez les brochettes." },
    [2795] = { "Un plat de nains, ce qui veut dire qu'il arrive avec une histoire sur le grand-père qui l'a inventé, et que l'histoire change selon celui qui la raconte. Je ne prends pas parti. Les côtes et la bière sont honnêtes, quel que soit le premier à les avoir cuites. Tous les nains dont j'ai entendu parler arrosent dès la première minute, puis accusent le feu de la suite. Rôtissez les côtes à nu jusqu'à ce que la graisse coule claire, et alors seulement commencez la bière, un peu à la fois, pour qu'elle devienne un glaçage. Quand elle sent le sucre brûlé, c'est allé trop loin. Quand elle sent le pain et la fumée, c'est parfait. Les gardes noirs demandent celui-ci par son nom, ce qu'ils ne font même pas pour leurs sergents. Je le prépare les jours de fête, et les jours qui en ont besoin." },
    [3370] = { "Le crocilisque arrive à Fossoyeuse depuis les Paluns, par des gens qui préfèrent ne pas dire comment. Je ne demande rien. La viande est pâle et ferme, plus poisson que bête, et elle veut une pincée d'épices et très peu de temps. Cuisez-la une fois. Le crocilisque réchauffé sent le marais, et personne n'a commandé le marais. Servez-le tout de suite, à qui se tient le plus près." },
    [3371] = { "Chaque automne, les fermes de Lordaeron faisaient le boudin, et chaque automne la grand-mère de quelqu'un connaissait la seule bonne façon de le faire. La mienne ne jurait que par le thym. Ou par la sauge. J'en ai été sûre pendant des années. Ici, c'est l'ichor d'araignée qui lie le tout, là où le sang le faisait autrefois, et la Société royale des apothicaires m'assure qu'il est sans danger pour les vivants, ce qu'elle ne dit pas de grand-chose. Les vivants en redemandent, et c'est la seule critique qui m'intéresse. Pochez les boudins avant qu'ils ne voient la poêle. Un boudin qui éclate a été rempli par quelqu'un de pressé." },
    [3372] = { "Deux ailerons de murloc et des épices fortes, mijotés jusqu'à ce que les ailerons fondent dans le bouillon et le laissent épais et riche, comme un fond d'os. L'odeur est celle de la mer à marée basse, ce qui paraît désagréable et ne l'est pas, une fois que l'épice s'en mêle. Les murlocs de la côte des Pins argentés protesteraient, s'ils savaient. Ils protestent contre presque tout, bruyamment, et j'ai cessé d'écouter depuis longtemps." },
    [3373] = { "De la viande de crocilisque tendre et des épices fortes, réduites jusqu'à ce que le bouillon soit épais et assez sombre pour napper une cuillère. La couleur vous renseigne, et l'odeur aussi : quand elle passe du marais à la noisette grillée, vous y êtes. Remuez par le fond, toujours. Je ne peux pas goûter un gombo, mais je sens un gombo brûlé depuis l'autre bout de Fossoyeuse, et tout le monde aussi, me dit-on." },
    [3376] = { "Un oeuf de raptor et des épices fortes. L'oeuf est plus riche que celui d'une poule et prend plus lentement, alors prenez patience avec le coeur. Battez-le fort, cuisez-le vite, pliez-le baveux. L'étrangeté, me dit-on, c'est qu'elle soit si bonne. Je ne peux pas vous le dire moi-même. Je peux vous dire que ceux qui la mangent se taisent, puis regardent l'assiette comme si elle leur devait une explication." },
    [3377] = { "Des pattes d'araignée, la chair tirée et pressée en galettes avec des épices fortes, frites jusqu'à ce que l'extérieur croustille et que le coeur reste tendre. Le fondant doit rester au coeur. S'il coule dans la poêle, vous l'entendrez siffler et le sentirez brûler, et la galette est perdue. Faites-les frire à chaleur régulière, pas féroce. J'en fais par plateaux entiers. Les araignées sont la seule chose que Fossoyeuse peut toujours offrir à un invité." },
    [3397] = { "Les ours du sud sont plus grands que les nôtres, et leur viande est plus sombre, avec une odeur de pin et de terre mouillée que les épices fortes tranchent. Saisissez le steak jusqu'à ce qu'il sente la fumée et le fer, puis laissez-le reposer longtemps. Un gros steak continue de cuire après le feu, et plus d'un cuisinier en a gâché un à force de le fixer. Je dis à mes élèves de s'éloigner et de compter jusqu'à cent, puis de me dire quel goût il a. La plupart arrivent à quarante." },
    [3398] = { "Les lions des Tarides sont maigres et doux près de l'os, alors les côtelettes restent sur l'os. Des épices fortes, un feu modéré et beaucoup de retournements. Je ne peux pas vous dire à quel point elles sont relevées. Je peux vous dire que les orcs de la Croisée en redemandent à chaque fois et que les trolls en veulent moins, alors je fais deux poêles et je les laisse se disputer pour savoir laquelle est la bonne." },
    [3399] = { "Du lion cuit en steak plutôt qu'en côtelettes, avec des épices apaisantes pour arrondir la douceur de la viande. L'épice apaisante sent le clou de girofle et la pierre tiède. Frottez-la, saisissez le steak fort, laissez-le reposer aussi longtemps que vous l'avez saisi. Tranchez contre le fil, sinon il se défend dans la bouche. Le nom a été écrit par quelqu'un qui l'avait mangé et qui était trop occupé pour trouver mieux." },
    [3400] = { "De la tortue et des épices apaisantes, mijotées des heures, puis passées au tamis jusqu'à être lisses comme de la crème. Le tamis, c'est la recette. L'odeur pendant que ça mijote est chaude et ronde, comme des clous de girofle dans une pièce fermée, et elle ralentit les gens qui passent devant ma cuisine. J'aime un plat qui ralentit les gens. Ici, tout le monde est si pressé d'aller quelque part où il est déjà allé." },
    [4094] = { "Il y a plus de busards que de cuisiniers dans les Tarides, et les cuisiniers leur ont trouvé un usage. L'aile veut des épices fortes, une longue chaleur douce pour attendrir les tendons, puis une flamme brève et féroce pour cloquer la peau. On entend le changement. La graisse cesse de chuchoter et se met à crépiter. Servez-les chaudes et en quantité. Personne n'a jamais mangé une seule aile de busard." },
    [6412] = { "Une recette elfique, venue d'un arbre si haut que les elfes de la nuit, dit-on, cuisinent dans ses branches. Je n'y suis jamais allée, et l'on ne m'y attend pas. La recette m'est parvenue par trois marchands, dont deux honnêtes. Enfilez les pattes d'araignée sur une brochette et donnez-leur une chaleur vive et brève, jusqu'à ce que les carapaces craquent comme des brindilles dans un feu. Ce bruit est le signal. Après lui, chaque instant vous coûte." },
    [6413] = { "Les cuisiniers d'Orgrimmar ont envoyé ce plat vers le nord avec les premiers zeppelins, et Fossoyeuse l'a adopté. La surprise est dans le dard. Cuit jusqu'à passer du verre à la craie, il perd son venin et garde un croquant agréable. Pas assez cuit, il garde le venin, et la surprise est d'un autre genre. On entend le changement. Un dard cru cliquette dans la poêle. Un dard cuit se tient tranquille." },
    [6414] = { "Les taurens de Mulgore rôtissent le kodo comme ils font la plupart des choses, lentement et sans histoires. Je le cuisine de la même façon. Le kodo est un grand animal lent, et sa viande reste dure jusqu'à ce qu'elle en décide autrement. Une pincée d'épices, un feu doux et un après-midi. C'est prêt quand ça sent l'herbe tiède et la fumée. Je ne peux pas le goûter, alors j'ai demandé à un marchand tauren, qui m'a dit que le mien était presque aussi bon que celui de sa mère. J'ai choisi de croire que le presque était de la politesse." },
    [6415] = { "Les furies ne sont que dents et colère, et leur chair est ce qu'elles ont de plus tendre. Un filet se défait si on le regarde trop longtemps. Assaisonnez-le légèrement, posez-le côté peau dans une poêle chaude, retournez-le une fois. L'odeur est douce et brève, partie en un souffle. Quand elle s'efface, le poisson est cuit. La recette vient de Sombrivage, par une elfe qui ne voulait de moi qu'un prix juste, ce qui est plus rare que cela ne devrait l'être." },
    [6416] = { "Du trotteur et de la pomme, le premier ragoût des Tarides. La pomme entre avec la viande et fond jusqu'à disparaître, et quand on ne la trouve plus dans la marmite, le ragoût est prêt. Le trotteur est un oiseau têtu. La pomme le raisonne. Je le prépare pour les orcs qui regrettent leur pays et pour les trolls qui n'ont jamais eu de pays à regretter, et ils le mangent tous de la même façon, très vite." },
    [6417] = { "Les Tarides m'ont appris celui-ci, et Fossoyeuse l'a adopté, parce que nous ne manquons pas de rats non plus, même si les nôtres ne sont pas bons à manger et que les rats fouisseurs des Tarides le sont. Faites-les mijoter longtemps, jusqu'à ce que la viande tombe des petits os, et retirez les os avec patience et une cuillère. Mes élèves font la grimace. Je les fais manger. Puis ils le préparent eux-mêmes, pour les élèves suivants, et les grimaces continuent." },
    [6418] = { "Les Tarides m'ont appris celui-ci, avec la patience et le respect de tout ce qui y survit. Une queue de lézard-tonnerre est un muscle plein, enveloppé d'une peau comme du vieux cuir. Cuisez-la dans sa propre graisse avec des épices fortes jusqu'à ce que la peau craque sous une cuillère. Si elle plie, ce n'est pas cuit. Si elle éclate, c'est parfait. Les orcs la mangent entière. Moi, je la coupe en rondelles, par égard pour le mobilier." },
    [6419] = { "Il y avait des cerfs dans les bois au-dessus de la ferme, et mon père, ou mon oncle, ou un voisin avec un arc, en abattait un chaque automne. Le visage est parti. L'odeur de la viande dans la poêle, non. La venaison est maigre et fière et veut beaucoup d'épices et très peu de feu. Retirez-la tant que le coeur est encore sombre. Une viande maigre cuite à coeur n'a le goût que du regret." },
    [6499] = { "Les palourdes sont honnêtes. Elles vous disent quand elles sont prêtes, pour peu que vous gardiez le nez au-dessus de la marmite. La vapeur sent d'abord le sucré, puis la mer, et c'est le moment de les sortir. Les palourdes ne pardonnent rien, et j'apprécie cela chez un aliment. Un voyageur descendu du zeppelin en a mangé deux bols debout à mon comptoir, puis il a demandé s'il y en avait un troisième. Il n'y en avait pas. J'en prépare davantage, maintenant." },
    [6500] = { "Les gobelins mettent trop de chaleur dans tout, palourdes comprises. Je l'enseigne la chaleur corrigée. De la chair de palourde relevée, des épices fortes, un feu chaud sans être furieux. L'odeur vous dira quand vous arrêter : quand l'épice cesse de sentir le cru et se met à sentir le grillé, retirez la poêle. Une palourde cuite avec fureur devient du cuir. Les gobelins vous vendraient le cuir en l'appelant moelleux." },
    [6501] = { "Il y avait à Austrivage une maison qui servait de la soupe de palourdes, ou une femme qui en vendait sur le pas de sa porte, et l'odeur portait jusqu'au port. Je me souviens exactement de l'odeur et pas du tout de la porte. Chauffez doucement le lait glacé, ajoutez la chair de palourde et une pincée d'épices douces, et restez sous le frémissement. Le lait qui bout tranche, et on le sent arriver, une note aigre dans la vapeur. Si vous la sentez, recommencez." },
    [7213] = { "Une palourde géante est dense et douce, et à Baie-du-Butin on la fait flamber dans des épices fortes pour les pirates. Tranchez-la fin avant que la chaleur ne la touche, pour que l'épice la traverse, puis faites-la flamber fort et vite. La fumée vous fera pleurer. C'est ainsi que vous savez que vous avez mis assez d'épices. Quand la fumée se dissipe, le plat est prêt. Servez-le à quelqu'un qui a l'estomac solide et la mémoire courte." },
    [7751] = { "Les enfants en pêchent au bout de chaque ponton de Tirisfal, et je leur achète leurs seaux, parce qu'un enfant avec un poisson mérite une pièce. Cuisez-les entiers dans une poêle chaude, une poignée à la fois. Leurs yeux se troublent quand ils sont cuits, ce qui est le plus aimable des signaux : le poisson vous le dit lui-même. Les élèves qui ne savent rien faire d'autre savent faire cela, et je les fais commencer ici pour qu'ils aient de quoi être fiers." },
    [7752] = { "Le maquereau est gras, et la graisse est tout l'intérêt. Posez-le côté peau dans une poêle chaude et sèche et laissez sa propre graisse le cuire. L'odeur emplit la cuisine, monte l'escalier et gagne la rue, et quelqu'un descend toujours demander ce que c'est. C'est ainsi que je trouve la plupart de mes clients. Le poisson fait sa réclame mieux que moi, et il ne demande pas de gages." },
    [7753] = { "La vase est dans la peau, pas dans la chair, et on la sent dès que le poisson rencontre la chaleur. Cuisez-le entier sur un feu modéré et retirez la peau avant de servir. La chair dessous ne sent rien d'autre que le poisson, ce qui est exactement ce qu'on attend d'un poisson. Les pêcheurs de Tirisfal mangent aussi la peau. Ils disent qu'elle leur rappelle la rivière. Ils n'avaient pas besoin de le dire." },
    [7754] = { "L'eau froide du loch donne un poisson plus ferme que les furies du sud, et les nains l'ont appelé un délice, ce qui, me dit-on, leur ressemble peu. Une pincée d'épices douces, un feu vif, et servez-le chaud. L'odeur est nette et froide, comme un matin au bord d'un lac. Je ne suis jamais allée au Loch Modan. Je suis allée au bord de lacs. J'imagine que c'est pareil, avec plus de cris." },
    [7755] = { "Le poisson-chat, c'était ce que la rivière nous donnait quand elle nous donnait quelque chose, et ma mère le dépouillait sur la marche de derrière, ou ma grand-mère. Retirez toujours la peau. Elle sent le lit de la rivière, et le lit de la rivière n'est pas un souper. La chair dessous est blanche et douce et veut une poêle chaude et un seul retournement. J'entends encore ce couteau sur la marche. Je ne vois plus la main qui le tenait." },
    [7827] = { "Ferme, sombre et riche, plus viande que poisson, et il faut le cuire comme une viande : une saisie franche dehors et très peu au coeur. La couleur vous renseigne. Rose dedans, c'est juste, gris, c'est trop. Je ne peux pas goûter la différence. Je peux la voir, et le visage de celui qui le mange la voit aussi. Le rose vaut un hochement de tête. Le gris vaut de la politesse, ce qui est pire." },
    [7828] = { "Ses écailles émousseraient un mauvais couteau, alors achetez-en un bon avant d'acheter le poisson. Retirez-lui ses écailles dehors, si vous pouvez. Les écailles vont partout et on les retrouve pendant des semaines. Puis une poêle chaude et un seul retournement. La chair se défait en feuillets blancs et nets et sent l'eau froide et le sel. Elle n'a besoin de rien. Je ne lui donne rien, et mes élèves apprennent que rien est parfois la chose la plus difficile à donner." },
    [8238] = { "Les poissons déviants viennent des bassins empoisonnés des Cavernes des lamentations, et ceux qui les ont empoisonnés ne voulaient pas les rendre délicieux. Ils le sont, un peu. Cuisez le poisson à coeur, avec des épices douces, et ne le laissez pas sous-cuit. Les apothicaires s'intéressent beaucoup à ce qu'il fait aux vivants. J'ai regardé. Je dirai seulement que c'est le seul plat que mes clients aient jamais mangé deux fois, pour voir ce qui se passerait." },
    [8604] = { "Un oeuf est la première chose que j'enseigne, parce qu'il vous dit tout par son odeur bien avant de vous dire quoi que ce soit par son goût. Quand la cuisine sent l'épice chaude et rien d'autre, il est cuit. Quand elle sent quelque chose de plus âcre, recommencez plutôt que de discuter avec lui. L'oeuf a toujours raison. Mes élèves le trouvent indigne d'eux. Un oeuf en a humilié davantage que n'importe quel sanglier." },
    [8607] = { "Ni épices ni sauce, seulement la fumée et le temps. C'est la nourriture des gens qui vont quelque part. Coupez la viande dans le sens des fibres et suspendez-la haut au-dessus d'un petit feu de bois vert, là où la chaleur n'arrive pas et où la fumée fait tout le travail. Au matin, les lanières doivent plier avant de casser. J'en prépare pour les gardes noirs, sur la route du Sépulcre. Ils n'ont pas besoin de manger, et ils en prennent trois chacun." },
    [9513] = { "Du chardonnier infusé dans de l'eau de source jusqu'à ce qu'il tourne au vert doré, puis filtré. Tous les voleurs de Fossoyeuse en boivent avant le travail, et Fossoyeuse compte beaucoup de voleurs. Ils viennent à mon comptoir à des heures étranges et paient le compte exact. Ne le laissez pas infuser trop longtemps. Il devient amer, et les voleurs, qui l'aiment amer, le boiront quand même et repartiront sans un mot." },
    [13028] = { "Une dorépine donne quatre tasses, ce qui vous dit sa force. Infusez-la dans une eau tout juste retirée du feu jusqu'à ce qu'elle prenne la couleur du vieux laiton, puis filtrez fort. L'odeur est vive et claire, comme une épée qu'on astique. Tous les gardes noirs des remparts en boivent, et aucun n'en a besoin. Ils ne le goûtent pas mieux que moi. Je crois qu'ils aiment la chaleur de la tasse entre leurs mains. Je ne leur ai jamais demandé." },
    [15853] = { "Un steak tout simple, pris au flanc d'un loup, avec une pincée d'épices et rien derrière quoi se cacher. C'est ce qui en fait une épreuve. Saisissez vite, laissez reposer longtemps, tranchez fin contre le fil. Je le juge à sa couleur et au visage de celui qui le mange, puisque je ne peux faire autrement. Je le fais cuisiner à mes élèves jusqu'à ce qu'ils ne tressaillent plus au sifflement de la poêle. Certains mettent une semaine. L'un d'eux a mis un an." },
    [15855] = { "Les camps de Strangleronce rôtissent le raptor en gros morceaux, et moi aussi, parce que le raptor est maigre et qu'un gros morceau garde son coeur moelleux. Des épices fortes dehors, un feu vigoureux, puis éloignez-le de la chaleur pour finir. L'odeur passe du métal à la fumée, puis aux noix grillées. Quelque part autour des noix, retirez-le. Le raptor s'est bien battu. Ne le laissez pas gagner à table." },
    [15856] = { "Des loups rouges du grand sud, plus gras que les loups gris des Pins argentés, avec des côtes qui ont besoin de temps pour fondre. Des épices fortes et un feu vif, puis de la patience. La graisse coule claire avant de fumer, et c'est le moment entre les deux qu'il vous faut. Les gardes noirs qui reviennent du sud en rapportent, enveloppées dans un linge, comme s'ils avaient trouvé un trésor. Pour une cuisinière, ils en avaient trouvé un." },
    [15861] = { "De la viande de tigre, de l'eau de source et des pommes, le ragoût de Strangleronce. Faites d'abord dorer la viande, puis ajoutez l'eau et les pommes et laissez mijoter jusqu'à ce que le fruit soit passé dans le bouillon. L'odeur devient sucrée, puis profonde, puis sucrée de nouveau. La seconde douceur veut dire que c'est prêt. Des trolls me l'ont appris, des Darkspear en route vers un endroit plus chaud. Ils disaient qu'il a le goût de chez eux. Je les ai crus sur parole." },
    [15863] = { "Les trolls du marais appellent ceci une tourte, et ils le disent gentiment. De la viande mystère et des épices fortes, cuites jusqu'à ce qu'il ne reste aucun doute sur rien. Je sens ce qu'était la viande, ce qui est plus que les trolls ne peuvent en dire, et je la sers quand même. Cuisez à coeur, puis recommencez. Quoi qu'elle ait été, elle a fait un long voyage, et elle mérite une fin franche." },
    [15865] = { "De la viande mystère mijotée dans de la bière naine, et pour moi, il n'y a de mystère ni dans l'une ni dans l'autre. Je sens exactement ce qu'était la viande. Je sens la brasserie d'où vient la bière, et ce qu'on a renversé sur son sol. Ici, où l'on démêle les mystères au nez pour gagner sa vie, ce plat tient plutôt de l'autobiographie. Faites-le cuire longtemps et doucement, et ne le laissez jamais bouillir, sinon la bière tourne et vous le sentirez depuis l'escalier. Écumez la marmite pendant qu'elle mijote. La bière rend la viande sombre et tendre et donne au bouillon une amertume que les vivants semblent beaucoup aimer. Les apothicaires, qui devraient être plus avisés, en mangent des quantités et refusent de dire ce qu'ils croient qu'il contient. J'ai cessé de le leur dire. Ils l'apprécient davantage sans savoir, et tout le monde aussi, je crois." },
    [15906] = { "La viande mystère n'a aucun mystère pour moi. Je sens exactement ce qu'elle était, et la plupart du temps je préfère ne pas le dire. Ce sont les Tarides qui m'ont appris ce plat, pas Lordaeron, qui n'a jamais rien mangé qui se défende à ce point. Je ne peux pas vous dire à quel point il est fort. Je peux vous dire que les épices grillées me piquent les yeux, la seule chose que j'en ressens encore, et que le dernier tauren qui a goûté le mien a posé sa cuillère avec beaucoup de précaution avant de demander de l'eau, d'une voix que je ne lui connaissais pas. Percez le sac de flammes avant qu'il n'entre, sinon il se percera tout seul. Faites-le pour des gens que vous aimez, et prévenez-les. Puis regardez leur visage. Le plat est réussi quand ils se taisent." },
    [15910] = { "Les kodos de Désolace sont plus lourds que ceux des Tarides, nourris de presque rien, et leur viande est la plus dense que je connaisse. Les taurens m'ont appris ce ragoût, et je n'y ai jamais rien changé, parce qu'il n'y a rien à changer. Deux portions de viande de kodo épaisse, des épices apaisantes et de l'eau de source, et toute une journée sur un feu doux. Vous le sentirez tourner : cru, puis herbeux, puis profond et brun, comme un champ après la pluie. Quelque part dans la soirée, la viande se défait en fils au contact d'une cuillère. C'est le moment, et aucun autre. Je le prépare les jours les plus froids pour les gardes noirs sur les remparts, et je le monte moi-même. Ils n'en ont pas besoin. Ils font la queue quand même, et ils sont très silencieux en mangeant." },
    [15915] = { "De la viande de crabe tendre et beaucoup d'épices fortes, remuées sans cesse dans une poêle assez chaude pour vous faire reculer. L'épice doit cuire dans le crabe, pas rester posée dessus. Je ne peux pas vous dire à quel point c'est fort. Je peux vous dire que les trolls le mangent sans ciller et que les orcs le mangent en faisant semblant de ne pas ciller, et je sers les deux avec le même visage impassible." },
    [15933] = { "Un seul oeuf géant nourrit une table, et à Fossoyeuse, une table, c'est quiconque se tient le plus près du fourneau. Les oeufs viennent des grands oiseaux du nord, de Gangrebois et du Berceau-de-l’Hiver, rapportés par des marchands qui ont appris à ne pas dire où ils les ont trouvés. Battez l'oeuf avec des épices apaisantes jusqu'à ce qu'il soit lisse et pâle, puis versez-le dans la plus large poêle que vous ayez, sur un feu modéré, et ramenez les bords à mesure qu'ils prennent. L'odeur vous guide : chaude et ronde d'abord, puis noisette sur les bords. Noisette, c'est le moment de plier. Brun, c'est trop tard. Portez-la à table à deux mains. J'ai vu toute une patrouille de gardes noirs en partager une en silence, avec un grand soin, comme un trésor. Un instant, c'en était un. Puis ils en ont demandé une autre, et c'était le meilleur moment." },
    [15935] = { "Tous les nouveaux cuisiniers de Tirisfal en font, parce que les chauves-souris sont partout et qu'il ne reste pas grand-chose d'autre. J'en ai préparé plus que n'importe quel plat de ma première vie. Incisez la peau de l'aile et posez-la sur une plaque bien chaude, côté peau, puis n'y touchez plus. Elle parle pendant qu'elle cuit. Quand le sifflement devient crépitement, retournez-la une fois, et plus jamais. Servez-la à qui a encore faim. Ici, à Fossoyeuse, il y a toujours quelqu'un." },
    [18238] = { "Ferme et gras, des eaux chaudes au large de Tanaris, et d'autant meilleur qu'on en fait moins. Une poêle chaude, un seul retournement. L'odeur quand il est cuit est nette et vive, comme une brise marine qui n'a pas encore rencontré les quais. Mes élèves veulent ajouter des choses. Je leur retire le pot d'épices et le leur rends une fois le poisson mangé. La plupart ne le redemandent jamais." },
    [18239] = { "Un gros poisson riche du sud chaud, taillé en tranches assez épaisses pour reposer comme une viande. Les épices apaisantes arrondissent sa richesse sans la cacher. Saisissez les tranches fort, laissez-les reposer, servez-les. L'odeur est si riche qu'elle en devient presque sucrée, et elle porte loin. Quand je cuis du barracuda, la file à mon comptoir commence avant que le poisson soit prêt. Elle ne commence jamais si tôt pour les plats dont je suis fière." },
    [18240] = { "Un instant ou une heure, rien entre les deux. Je choisis l'instant. Quadrillez le calmar au couteau, frottez un peu d'épices apaisantes dans les entailles et posez-le sur le gril le plus chaud que vous ayez. Il se recourbe comme s'il était surpris. Quand les bords noircissent, il est cuit. L'odeur est sucrée et fumée, et elle tire les clients de la rue comme une corde." },
    [18241] = { "Le rouget n'a besoin que d'une poêle chaude. Posez le filet côté peau et attendez qu'il se décolle tout seul. C'est toute la leçon, et la plupart des élèves mettent un mois à l'apprendre, parce qu'attendre est plus difficile que faire. L'odeur passe du cru au sucré, et les bords passent du verre au blanc. Retirez-le alors. Il vous a dit tout ce qu'il savait." },
    [18242] = { "Fumée chaude et de près, pour que le poisson cuise en fumant. Frottez la perche d'épices fortes et suspendez-la juste au-dessus d'un feu fumeux. Surveillez la chair : quand elle passe du verre au blanc, décrochez-la. Une perche fumée ainsi se garde des jours. J'en prépare pour les voyageurs qui prennent le zeppelin, qui ont toujours faim et sont toujours en retard, et qui la mangent avant que le zeppelin ait quitté la tour." },
    [18243] = { "Un lutjan pêché la nuit, de l'eau de source, et rien d'autre. Faites frémir le poisson doucement jusqu'à ce que la chair tombe des arêtes, puis retirez les arêtes avec soin. Le bouillon doit être assez clair pour qu'on lise au travers. Il ne sent presque rien, et c'est tout l'intérêt : une soupe nette et calme pour des gens qui ont eu une journée bruyante. Je la prépare pour moi, le soir, et cela ne me gêne pas de ne pas pouvoir la goûter." },
    [18244] = { "Une eau qui ne bout jamais tout à fait, pour un poisson qui se déferait sous toute chose plus rude. Amenez-la à frémir, descendez-y le saumon et laissez-le tranquille. Vous le verrez passer du vif au pâle, comme s'il rougissait à l'envers. Sortez-le alors. Pocher est ce que je fais de plus doux en cuisine, et c'est ce que mes élèves trouvent le plus difficile, parce qu'il ne se passe rien pendant si longtemps." },
    [18245] = { "Du homard pince-noire dans de l'eau de source, et c'est tout. Descendez le homard entier et sortez-le à l'instant où sa carapace rougit. Retirez la chair de la carapace et réchauffez-la dans le bouillon. Ne le faites jamais bouillir deux fois. L'odeur d'un homard qui va trop loin est aiguë et reconnaissable entre toutes, comme du cuivre chaud, et une fois qu'on l'a sentie, on ne la laisse plus jamais arriver. Je l'ai laissée arriver une fois. C'était assez." },
    [18246] = { "Un grand barracuda est assez gros pour être découpé en steaks comme du boeuf, et il faut le cuire comme du boeuf. Des épices fortes pour le réveiller, des épices apaisantes pour le calmer, une saisie franche des deux côtés et un long repos. L'odeur est celle de la mer et d'une forge à la fois. Je le sers aux gardes noirs les soirs qui précèdent une longue patrouille. Ils ne disent rien, ce que disent les gardes noirs quand une chose est bonne." },
    [18247] = { "Un saumon entier des rivières froides, cuit au four avec des épices apaisantes à chaleur modérée. Entier, parce que la peau garde la chair moelleuse, comme un couvercle sur une marmite. Quand l'oeil blanchit et que la nageoire se détache au moindre contact, c'est cuit. La cuisine sent les rivières et l'épice chaude, et les apothicaires descendent emprunter des choses dont ils n'ont pas besoin, et repartent avec une assiette." },
    [20626] = { "Une soupe gobeline de Tanaris : de la chair de palourde piquante, des épices fortes et du lait glacé, chauffés ensemble sans jamais bouillir. Les gobelins la mangent brûlante, ce qui vous dit tout des gobelins. Gardez le feu bas et surveillez la vapeur. Quand elle sent la mer et l'épice chaude, et pas encore le lait brûlé, servez à la louche. Le gobelin qui la vend n'en garde qu'un exemplaire à la fois. Je l'ai acheté, et maintenant il y en a deux." },
    [20916] = { "Un poisson de montagne froid, à la tête d'argent et au caractère de bagarreur. Cuisez-la entière, avec la peau, dans une poêle chaude, et arrosez-la de sa propre graisse. Quand la peau cloque et que l'oeil blanchit, elle est cuite. Laissez la tête. Mes élèves demandent pourquoi. Je leur dis que le poisson s'est donné du mal pour la garder, et que le moins qu'on puisse faire est de la laisser venir à table." },
    [21143] = { "Le Voile d'hiver, en Lordaeron, sentait ces biscuits, toutes les cuisines de la rue à la fois, ou du moins je le crois. Je me souviens si nettement de l'odeur qu'il m'arrive de la sentir à Fossoyeuse en plein été, ce qui ne peut pas être vrai. Des épices spéciales et un oeuf, travaillés ensemble et cuits jusqu'à ce que les bords foncent et que le coeur cède encore. Ils durcissent en refroidissant. J'en fais à chaque Voile d'hiver pour les enfants des équipages des zeppelins. Ils ne demandent pas pourquoi j'en fais autant." },
    [21144] = { "Le Voile d'hiver, et l'oncle de quelqu'un qui fait du lait de poule dans un grand saladier, trop fort, chaque année. Je ne vois pas son visage, mais je l'entends chanter. Un oeuf, du lait glacé, de l'eau-de-vie spéciale et des épices spéciales, battus jusqu'à ce que ce soit pâle et épais. L'eau-de-vie entre en dernier et avec modération, ce dont aucun oncle n'a jamais fait preuve. Cela sent la muscade, le bois tiède et un peu les ennuis. Servez-le froid et gardez un oeil sur le saladier." },
    [21175] = { "Les araignées sont la seule chose dont Fossoyeuse ne manque jamais. La viande d'araignée blanche est douce et délicate et ne prend aucune épice, ce qui est une bénédiction dans une ville qui sent tout. Pressez-la dans des boyaux assez fermes pour tenir et assez fins pour craquer. Dans la poêle, guettez le claquement. C'est le bruit le plus satisfaisant de ma cuisine, et mes élèves apprennent à l'attendre." },
    [22480] = { "Les loups des contrées froides vivent lentement et gardent leur graisse, et leur viande est la meilleure de tous les loups. Des épices apaisantes, une saisie brève et vive, un long repos. Vous sentirez quand c'est prêt : l'épice se réchauffe et la viande devient douce, comme une miche tout juste sortie du four. Mes élèves jurent qu'ils sentent la différence dès la première bouchée, et je les crois, parce qu'ils se taisent. Un cuisinier qui a affronté cent loups faméliques mérite celui-ci. Je le sers à mes meilleurs élèves." },
    [22761] = { "La recette vient d'un diablotin des ruines de Hache-tripes, qui entraîne quiconque la veut dans une longue course stupide. Un de mes élèves a fait la course et en est revenu avec la recette, deux nouvelles cicatrices et beaucoup à dire sur les diablotins. La racine de courante pousse dans l'ombre de ces ruines, et c'est la meilleure racine que je connaisse, terreuse et douce. Pelez-la, tranchez-la épais et rôtissez-la lentement avec des épices apaisantes jusqu'à ce que les bords foncent et que le coeur cède sous la fourchette. Vous sentirez quand c'est juste : comme des châtaignes au coin d'une rue en hiver. Ce n'est pas mon souvenir, c'est celui de mon élève, qui l'a si bien décrit que je le lui ai emprunté. Les gardes noirs l'aiment parce qu'elle les remplit. Les vivants l'aiment parce qu'elle a le goût, me disent-ils, d'un endroit sûr. J'en fais beaucoup." },
    [24418] = { "Deux fois plus de crocilisque, des épices apaisantes, et un ragoût où une cuillère tient debout. Remuez par le fond, souvent, parce qu'un ragoût aussi épais attache et brûle là où vous ne le voyez pas, et l'odeur ne vous trahit que lorsqu'il est trop tard. Les soldats des marais le mangent dans des bols en fer-blanc sous la pluie, me dit-on. Mes gardes noirs le mangent dans des bols en fer-blanc au sec. Les bols en fer-blanc sont les mêmes partout." },
    [24801] = { "Le Cercle cénarien l'enseigne en Silithus à ceux qui ont fait leurs preuves dans le désert, et les soldats de la Horde l'ont rapportée parmi leurs cicatrices. La chair de ver des sables est dense, pâle et pleine de sable. Lavez-la jusqu'à ce que l'eau soit claire, hachez-la fin avec des épices apaisantes et roulez-la en petites boulettes bien serrées, pour qu'elles tiennent dans la fumée. Puis fumez-les lentement sur un feu doux. La fumée parfume l'extérieur pendant que la vapeur cuit le coeur, et l'odeur passe du cru au sucré, puis à quelque chose comme le grain grillé. Quand elle arrive au grain, elles sont prêtes. Je ne peux pas vous dire quel goût elles ont. Je peux vous dire qu'un soldat qui avait perdu trois amis dans ce désert en a mangé une assiette dans ma cuisine et a pleuré, puis il m'a demandé la recette, et je la lui ai donnée." },
    [25659] = { "Un gobelin de Gadgetzan cuit le chimaerok au carburant de fusée, et les voyageurs de la Horde rapportent la recette comme on relève un pari. La mienne vient d'un tauren qui avait perdu ses sourcils et gardé son appétit. Le filet de chimaerok est bien loin pour un morceau de viande, les îles au large de Feralas, et il vaut chaque pas. Du sel de Fonderoc, des épices fortes et le carburant de fusée des gobelins, qui va sur le feu, jamais dans la nourriture. Reculez plus loin que la politesse ne le voudrait. La flambée dure un souffle et laisse une croûte qu'aucun charbon honnête ne pourrait faire. L'odeur emplit tout l'Apothicarium, et les apothicaires sortent de leurs salles pour se plaindre et restent pour manger. Je ne leur demande pas ce qu'ils en pensent. Je compte les assiettes." },
    [25704] = { "Les sagerelles viennent des lacs de Hautebrande, où ma famille allait l'été, ou bien où nous disions toujours que nous irions. Le poisson sent la sauge des rives, et la fumée fait ressortir cette odeur. De l'odeur, je suis sûre. Des étés, beaucoup moins. Une fumée basse, une pincée d'épices douces et un après-midi. Quand la chair dore et sent les herbes et la fumée de bois, c'est prêt." },
    [25954] = { "La grande sagerelle, engraissée de la sauge de son lac, avec des épices fortes pour la réveiller. Saisissez le filet côté peau jusqu'à ce que la peau crépite, puis retournez-le le temps d'un souffle. L'odeur est le délice : verte, chaude et poivrée, tout à la fois. Je le prépare quand je veux que la cuisine sente autre chose que la ville au-dessus, c'est-à-dire presque tous les jours, pour être honnête." },
    [470359] = { "De l'eau sacrée de Stratholme, que les apothicaires m'ont tendue sans sourire. Je suis allée à Stratholme une fois, vivante, pour un marché ou un mariage, et je me souviens des cloches et du pain, et de rien d'autre. Maintenant, son eau fait une bisque. Du homard pince-noire, frémissant dedans jusqu'à ce que la carapace rougisse, puis tamisé jusqu'à être lisse. L'eau est très douce et très propre, et elle ne me brûle pas. Elle laisse le homard parler. J'écoute." },
    [470370] = { "L'expédition de Silithus vend ceci aux soldats qui ont besoin d'une nourriture qui tienne dans le sable. Du rouget, fumé lentement jusqu'à être assez sec pour être emporté et encore assez tendre pour être mangé. Pas d'épices. La fumée et le temps font le travail. Je l'ai appris d'un apothicaire revenu du désert avec cette recette et pas grand-chose d'autre. Il disait que c'était la seule chose là-bas qui n'avait pas essayé de le tuer." },
    [1225758] = { "Du tigre, voilà ce que veut dire le nom, taillé épais et frotté de sels sacrés une heure avant la cuisson. Le tigre est une viande travailleuse, et le sel la calme. Puis un fer brûlant, une saisie brève et un long repos. Vous l'entendrez se détendre sur la planche, un léger affaissement, comme un chien qui se couche. C'est là qu'on tranche. Pas avant. Un tigre qui ne s'est pas posé ne se posera pas davantage à table." },
    [1225759] = { "Des sels sacrés, venus des églises des vivants, ce qui m'a fait rire la première fois que j'en ai tenu une bourse. Ce sont de bons sels. La Lumière n'a rien contre moi en cuisine. Frottez-les dans le flanc de loup rouge et laissez reposer une heure, puis cuisez vite. Le sel tire l'eau de la viande et la raffermit. Il ne me brûle pas, avant que vous ne demandiez. Mes élèves demandent toujours." },
    [1225760] = { "Deux oeufs géants et des sels sacrés, dont on m'avait dit qu'ils me brûleraient et qui ne me brûlent pas. Cuisez-la lentement, pour que le jaune reste vif comme le matin. L'odeur est nette et simple, l'oeuf, le sel et la poêle. Je la prépare à l'heure que les vivants appellent l'aube, ce qui ne veut rien dire ici, par une habitude que je ne me rappelle pas avoir prise. Quelqu'un vient toujours la chercher. Quelqu'un vient toujours." },
    [1225762] = { "Douze jaune-queues tachetés, trois morues rochécaille, quatre portions de raptor et des épices exquises, disposés sur la plus grande planche de la cuisine. Les morues d'abord, parce qu'elles sont épaisses. Le raptor rôtit et repose pendant que les poissons cuisent. Les jaune-queues en dernier, parce qu'ils sont rapides, et dès que leur peau se décolle du gril, ils sont prêts. L'odeur d'un festin de poisson est une marée qui monte : d'abord la mer, puis la fumée, puis l'épice. Quand l'épice arrive, commencez à porter les plats. Je l'ai préparé pour les équipages des zeppelins à la fin d'une longue saison, et les gobelins, qui ne sont pas sentimentaux, se sont assis à mon comptoir et ont mangé pendant une heure sans parler d'argent une seule fois. C'est la seule fois que j'ai vu un gobelin oublier de marchander. C'était le festin, pas moi." },
    [1225763] = { "Un banquet, c'est beaucoup de travail pour une seule soirée, et celui-ci plus que la plupart : douze homards pince-noire, quatre portions de tortue, trois ailes de busard et des épices exquises, qui sont surtout exquises par leur prix. La tortue mijote le plus longtemps, alors elle commence en premier. Le busard rôtit pendant que la tortue mijote. Les homards viennent en dernier, pochés par fournées et sortis dès que leur carapace rougit, avant que l'odeur ne tourne au cuivre. Tout doit arriver à table ensemble, et vous saurez que c'est prêt quand la salle sentira à la fois la mer, la forêt et l'âtre. Je l'ai cuisiné deux fois, pour les officiers de la Dame noire, qui n'ont rien dit et ont tout mangé. La seconde fois, l'un d'eux est descendu en cuisine pour me dire que c'était très bon. Il n'avait pas mangé de homard depuis qu'il était vivant. Il se souvenait de ce qu'un homard était censé être." },
    [1229737] = { "Avant le plat, le feu. Du bois simple, empilé sans serrer pour que l'air puisse circuler, allumé par le bas et laissé tranquille. Vous entendrez quand il sera prêt : le crépitement s'apaise en un bourdonnement sourd et les flammes s'enfoncent dans les braises. Cuisinez sur les braises, jamais sur les flammes. J'enseigne cela en premier, avant le loup, parce qu'un cuisinier sans feu est un invité, et je ne garde pas d'invités dans ma cuisine." },
    [1247741] = { "Une recette sans vendeur, pour l'instant, pour un poisson que je n'ai jamais vu. On me dit que le flétan épineux est large et blanc et armé le long du dos, ce qui est la façon dont les poissons disent qu'ils préféreraient ne pas être mangés. Cuisez-le en morceau épais, doucement, jusqu'à ce que les feuillets commencent tout juste à se séparer. Je l'écris pour que le premier cuisinier qui en attrape un sache par où commencer. Dites-moi quelle odeur il avait." },
    [1249957] = { "Du pacifique infusé dans de l'eau de source jusqu'à ce que l'eau prenne la couleur de la paille. Ne le faites pas bouillir, ou il sentira le foin et rien d'autre. Laissez-le infuser, et il sentira la lisière d'un champ le soir, derrière une maison que je ne situe plus, et c'est encore la meilleure odeur que je connaisse. Les trolls Frostmane en font, dit la recette. J'en prépare pour les apothicaires, qui ont plus besoin de paix que quiconque et en reçoivent moins que tout le monde." },
    [1249958] = { "Du mage royal infusé dans du lait tiède jusqu'à ce que le lait prenne une pâle teinte violette. En Lordaeron, on le servait à la cour, du moins c'est ce qu'on disait en cuisine, comme les cuisines disent des choses sur la cour. Je n'ai jamais vu un roi en boire. Je ne suis pas sûre d'avoir jamais vu un roi. Chauffez le lait doucement et ne le faites jamais bouillir, sinon il forme une peau. Autrefois, une peau sur un thé royal aurait coûté sa place à une cuisinière. Aujourd'hui, elle ne lui coûte rien, et je la retire encore." },
    [1249959] = { "De la vietérule, lavée et tranchée, infusée dans du jus de melon tiède jusqu'à ce que le jus fonce et sente à la fois la terre et l'été. Filtrez avec soin, parce qu'une racine laissée trop longtemps donne au thé le goût du sol. Je ne peux pas le goûter, mais je sens le sol arriver, une note lourde et humide sous la douceur. Retirez la racine avant qu'elle ne vienne. Les vivants le remarquent. Ils remarquent toujours ce que je ne peux pas sentir." },
    [1249960] = { "Du nectar sucré et de la pâlerette, un thé pour les blessés, bien que la pâlerette soit ce que mâchent les voleurs pour disparaître. Peut-être les blessés aimeraient-ils disparaître aussi. Chauffez le nectar jusqu'à ce qu'il fume, faites infuser la pâlerette et filtrez avant qu'elle ne devienne amère. On ne m'a pas vendu cette recette. Je l'ai faite d'après une description, pour les patients des apothicaires, qui ne se sont pas plaints, mais il faut dire qu'ils le peuvent rarement." },
    [1249961] = { "De la soleillette infusée dans du jus de baie lunaire jusqu'à ce que la boisson devienne dorée. Elle sent le foin l'après-midi et un mur tiède au soleil. Il n'y a pas de soleil à Fossoyeuse. Je prépare ce thé quand mes élèves sont devenus silencieux et pâles et commencent à oublier la surface, et je le leur mets entre les mains, et il la leur rappelle. Ce n'est pas dans la recette. Cela devrait y être." },
    [1249962] = { "De la sauge-argent des montagnes dans de la rosée matinale, deux choses difficiles à trouver, infusées ensemble en un thé qui sent l'air froid et la pierre. Chauffez doucement la rosée, faites-y infuser la sauge-argent jusqu'à ce que la boisson pâlisse, puis filtrez. Les vivants disent qu'il n'a pas grand goût, ce qui, d'après les apothicaires, aiguise l'esprit. Je crois surtout qu'il leur donne une excuse pour cesser de travailler le temps d'une tasse, et je ne conteste ni l'une ni l'autre croyance." },
    [1249963] = { "De l'eau de source, des épices douces et une petite glande à venin, écrasée et filtrée pour qu'il n'en reste que le piquant. Les apothicaires ont vérifié ma première fournée. Ils l'ont déclarée sans danger pour les vivants, avec une déception que j'ai choisi de ne pas relever. Secouez fort et servez froid. Les vivants disent qu'il mord la langue. Je les crois sur parole, et je les regarde tendre la main vers un second verre." },
    [1249964] = { "Du lait glacé, des épices douces et de l'ichor d'araignée, secoués jusqu'à ce que l'ichor renonce et se mélange. Cela sent un peu l'amande et beaucoup l'araignée. Servez-le aussitôt. S'il attend, il se sépare, et un frappé gélatineux séparé est une chose que personne ne devrait avoir à regarder. Les apothicaires en boivent au pichet en travaillant, ce qui vous apprend quelque chose sur les apothicaires, et je ne dirai pas quoi." },
    [1249965] = { "Je n'essaierai pas de prononcer le nom. Du jus de melon, des épices fortes et un aileron de murloc, secoués jusqu'à ce que l'aileron cède son corps au jus. Cela sent un melon parti au bord de la mer et revenu changé. Les murlocs des Pins argentés en seraient honorés, je crois, ou furieux. Avec les murlocs, c'est difficile à dire, et le bruit est le même. Je le sers aux courageux, et à ceux qui s'ennuient beaucoup." },
    [1249966] = { "Du nectar sucré, des épices fortes et un grand croc réduit en poudre. Le croc rend la boisson crayeuse et épaisse, comme du lait oublié au soleil. Filtrez-la bien, deux fois, parce qu'une boisson qui crisse sous la dent est la seule chose que personne ne pardonne. Les vivants qui se battent pour gagner leur vie en boivent le matin. Les gardes noirs, qui se battent pour gagner leur vie et ne vivent pas, en boivent par solidarité." },
    [1249967] = { "Du jus de baie lunaire, des épices apaisantes et un petit sac de flammes, percé et pressé dans le verre. Le sac de flammes chauffe et l'épice s'excuse. Secouez et buvez vite. Je ne peux pas vous dire à quel point c'est brûlant. Je peux vous dire que j'ai vu un jour un orc en boire un, puis rester immobile très longtemps, les yeux au plafond, comme si le plafond l'avait insulté." },
    [1249968] = { "De la rosée matinale, beaucoup d'épices apaisantes et une serre cruelle, moulue fin. La serre lui donne une arête sombre et amère que l'épice n'arrive jamais tout à fait à adoucir. Il sent les fleurs écrasées et quelque chose qui aimerait bien vous mordre. Servez-le froid. Les jeunes gardes noirs en boivent par défi. Les vieux en boivent parce qu'ils ont cessé de relever les défis, et ils l'aiment quand même." },
    [1250142] = { "De petites galettes de cerf haché et d'épices fortes, pressées une fois et frites vite. Pressez-les deux fois et le jus file dans la poêle au lieu de l'invité. Les vivants aiment la nourriture qui se mange d'une main. J'ai vu des dockers de la tour des zeppelins en finir une douzaine entre deux arrivées et retourner au travail sans un mot. C'est la seule critique qui compte." },
    [1250143] = { "Des ailes de busard, désossées et aplaties, roulées autour d'épices apaisantes et ficelées. C'est un travail lent et minutieux, et je le donne aux élèves qui sont fiers de leur couteau. Rôtissez doucement et tranchez en rondelles. La spirale à l'intérieur me dit tout du cuisinier qui l'a roulée. Une spirale serrée, une main soigneuse. Une spirale lâche, quelqu'un qui pensait au déjeuner." },
    [1250144] = { "Un ragoût de pauvre fermier, de la viande hachée cuite longtemps et doucement. En Lordaeron, c'était du boeuf, quand il y avait du boeuf, ou du moins je le crois. Ici, c'est de la chauve-souris. Hachez les ailes fin, ajoutez les épices apaisantes et donnez-lui un feu doux pendant une soirée, jusqu'à ce que les tendons fondent et que la cuisine sente le clou de girofle et quelque chose comme la maison. Mes élèves l'appellent la bouillie de chauve-souris. Moi, je l'appelle le souper." },
    [1250145] = { "De la tortue mijotée et non tamisée, un ragoût de ferme plutôt qu'une bisque de seigneur. Nous en faisions au bord d'une rivière en Lordaeron, j'en suis presque sûre, même si je ne saurais dire laquelle. Trois portions de tortue et beaucoup d'épices apaisantes, mijotées jusqu'à ce que la viande se défasse. Laissez-le épais. La texture est tout l'intérêt, et l'odeur, ronde, chaude et lente, est la raison pour laquelle les gens restent au comptoir une fois leur bol fini. J'ai cessé de leur demander de partir. Ils partiront quand le bol sera vide, et pas avant." },
    [1250146] = { "Il n'y a pas de poivre dedans, quoi qu'en dise le nom, seulement du flanchet de loup rouge et des épices apaisantes, qui font assez bien le travail du poivre. Saisissez le flanchet fort, laissez-le reposer pendant que la poêle refroidit, puis reversez son jus par-dessus. L'odeur quand le jus retrouve la viande chaude est tout l'intérêt du plat. Je le sers aux apothicaires quand je veux obtenir quelque chose d'eux, et cela marche." },
    [1250147] = { "De fines tranches de viande de grand ours en couches avec des épices apaisantes, rôties lentement jusqu'à ce que les couches se soudent. Tranchez la viande froide, sinon elle se déchire. L'odeur quand c'est prêt est le meilleur moment, sombre et douce, proche du sucre brûlé. Le nom ne me dit rien, ni à aucun de ceux à qui j'ai demandé. Celui qui l'a nommé faisait le malin. Celui qui l'a cuisiné le premier, non." },
    [1250148] = { "Du cerf, frotté d'épices apaisantes et saisi sur un fer très chaud, servi aussitôt, tant qu'il fume encore. La vapeur porte l'odeur, et l'odeur est la moitié du repas pour qui peut goûter, et tout le repas pour moi. Ne le faites pas attendre. Un steak qui cesse de fumer a commencé à refroidir, et un steak froid est une promesse que quelqu'un a rompue entre la cuisine et la table." },
    [1250149] = { "Du tigre et des épices apaisantes, le feu le plus vif que vous puissiez faire, le temps le plus court que vous puissiez supporter. Le nom est celui d'un chasseur. La méthode est celle d'un cuisinier. Frappez vite, puis laissez reposer longtemps, et c'est au repos que tout le monde échoue, parce que l'odeur est merveilleuse et que la fourchette est juste là. Je fais asseoir mes élèves sur leurs mains. La première fois, au sens propre." },
    [1250150] = { "Une recette que j'ai lue sans jamais me la faire vendre, ce qui me la rend suspecte. Les côtelettes cuisent à feu doux jusqu'à ce que la viande lâche l'os, puis sur une flamme féroce pour fixer une croûte d'épices fortes, et il y en a beaucoup. La fumée seule m'a fait pleurer les yeux. Je ne peux pas vous dire à quel point elles sont fortes. Je peux vous dire que personne de ceux à qui je les ai servies n'a demandé plus d'épices." },
    [1250151] = { "Le morceau le plus dur de l'animal le plus dur, et la raison pour laquelle un cuisinier apprend à garder un feu bas. Frottez la poitrine d'épices fortes et laissez-la cuire une journée entière, jusqu'à ce qu'elle cède sous la fourchette comme du pain mouillé. On ne peut pas la presser. On peut seulement la regarder, et la sentir passer du fer cru à la fumée, puis à quelque chose de riche et de sombre. Quand elle sent un soir d'hiver, elle est prête." },
    [1250152] = { "Du raptor cuit presque une journée sur le plus petit feu que je puisse tenir, avec beaucoup d'épices apaisantes, jusqu'à ce qu'il se défasse au contact d'une fourchette. Effilochez-le à deux fourchettes, jamais au couteau. Les gardes noirs l'adorent parce qu'il se conserve et qu'il se mange dans un bol en marchant. Préhistorique, dit-il de lui-même. Les manières de certains de mes élèves aussi." },
    [1250153] = { "De fines tranches de raptor roulées autour d'épices fortes et ficelées. Les rouleaux cuisent de l'extérieur vers l'intérieur, alors gardez le dernier tour fin. Dorez-les sur toutes les faces, puis baissez le feu et laissez-les. Quand la ficelle fonce et sent le foin brûlé, retirez-la avant que quelqu'un la voie. Un invité pardonne beaucoup de choses, mais pas la ficelle. C'est un invité qui me l'a appris." },
    [1250154] = { "On l'épice avant et après, parce que le raptor est maigre et que la première couche s'en va à la cuisson. J'ai appris à sentir le moment entre les deux. Quand les tranches cessent de siffler et se mettent à cliqueter, comme une poêle qui refroidit, retirez-les et assaisonnez-les de nouveau tant qu'elles sont assez chaudes pour boire l'épice. Mes élèves oublient toujours la seconde couche. Le plat les dénonce. Il sent la moitié d'une recette." },
    [1250155] = { "Deux oeufs géants et des épices fortes, remués sur un feu doux jusqu'à ce qu'ils prennent en grumeaux tendres. Cela demande du temps et une main sûre, et cela sent, tout du long, quelque chose de riche et de chaud, alors qu'il n'y a dans la poêle que l'oeuf et l'épice. Quand l'odeur devient plus aiguë, arrêtez. Les oeufs sont sur le point d'aller trop loin. J'en sers aux gardes noirs après la garde de nuit, et ils les mangent debout au comptoir, encore en armure." },
    [1250156] = { "Un oeuf de raptor est gros comme mes deux poings, et quand on le casse il sent un peu le marais où sa mère a marché. L'épice est là pour répondre à cette odeur, et il y en a beaucoup. Battez l'oeuf, assaisonnez-le et cuisez-le en petits disques sur une pierre chaude. Les disques gonflent quand ils sont cuits. Mes élèves les mangent avant que je puisse les compter, ce qui me dit que la recette fonctionne." },
    [1250157] = { "Un oeuf et beaucoup d'épices douces, plus que de raison, d'une recette trouvée dans le nid d'un condor des Carmines. Je l'ai faite telle qu'elle est écrite. Elle sent le matin et un marché aux épices, et une cuisine au sol de pierre que je situe presque. Battez l'oeuf jusqu'à n'avoir qu'une couleur, versez-le dans une poêle chaude et ramenez les bords à mesure qu'ils prennent. Pliez-la baveuse. Les vivants qui la mangent disent qu'elle les réveille. Les gardes noirs la mangent pour se rappeler ce qu'étaient les matins." },
    [1250158] = { "Il n'y a pas de pâtes dedans, quoi que promette le nom. Il y a de la chair de palourde piquante, en grande quantité, taillée en longs rubans et enrobée d'épices apaisantes. Cuisez un instant dans une poêle chaude et servez aussitôt, emmêlé. Cela se mange comme des pâtes et sent la mer. Je ne sais pas qui l'a inventé. Je soupçonne un cuisinier qui n'avait pas de farine et beaucoup de palourdes, et qui ne s'en est pas plaint." },
    [1252566] = { "Un petit poisson vif au nom ridicule. La recette apparaît dans les Carmines, dans les sacs de créatures qui ne cuisinent pas, ce qui veut dire que quelqu'un qui cuisinait l'a perdue là-bas. Une pincée d'épices douces, une poêle chaude, un instant. L'odeur est douce et brève, comme un fruit. Je le prépare quand les équipages des zeppelins amènent leurs enfants en bas, parce que le nom les fait rire, et le rire n'est pas assez fréquent par ici." },
    [1255241] = { "Une fleur gangrenée, purifiée par les druides pour qu'elle ne fasse plus ce que font ces fleurs-là. Je garde mes distances quand même, par habitude. La viande de cerf et un oeuf géant donnent au ragoût sa force, l'oeuf battu à la fin pour que le bouillon devienne soyeux. Il sent les choses vertes et le bouillon chaud et, faiblement, quelque chose de brûlé qui n'est plus là. Je le prépare pour ceux qui reviennent de Gangrebois avec l'air d'avoir ramené la forêt avec eux." },
    [1262978] = { "Macaron est le murloc qui cuisine pour les Défias dans les Mortemines, et celui qui lui a pris cette recette ne l'a pas demandée poliment. Deux portions de viande mystère, une de kodo épais et des épices apaisantes, rôties lentement ensemble jusqu'à ce que le kodo s'attendrisse et que le mystère s'épaississe. Je sens ce qu'était la viande mystère. Dans la cuisine de Macaron, j'aurais préféré ne pas le savoir. Un festin se partage, alors dressez-le sur un seul grand plat et laissez chacun se servir. Mes gardes noirs le font en silence, avec soin, chacun en laissant un peu pour le suivant, ce que les Défias n'ont jamais fait. L'odeur remplit la salle et fait descendre les vivants de la ville au-dessus, et j'ai cessé de les renvoyer. Le festin d'un murloc criminel, dans la cuisine d'une morte, mangé par quiconque a faim. Je crois que Macaron approuverait. Je crois qu'il voudrait récupérer sa louche." },
    [1263067] = { "De la farine, de l'eau de source et des épices apaisantes, dix mesures, cinq et quatre, pour un four en fer, dont la recette ne contient pas le moindre fer. Je crois que la pâte est travaillée dans le four neuf et cuite dure, pour le culotter, comme on culotte une poêle neuve. On ne m'a pas vendu la recette. Un marchand gobelin me l'a seulement décrite, persuadé qu'il m'impressionnerait. Il y est parvenu. Je ne le lui ai pas dit. Les gobelins sont insupportables quand ils ont impressionné quelqu'un, et ils le mettent sur la note." },
    [1270632] = { "De la farine et rien d'autre, cuite en petits biscuits pour les créatures qui suivent les aventuriers partout. J'en fais pour les rats de Fossoyeuse qui ont gagné mon respect, c'est-à-dire trois. Travaillez la farine légèrement et cuisez les biscuits pâles. Ils sentent le pain chaud et rien de plus, et c'est tant mieux, parce qu'un animal qui prend goût aux épices ne vous laissera plus jamais tranquille." },
    [1270633] = { "Deux oeufs et un peu de farine, les blancs montés jusqu'à se tenir, incorporés, et cuits sans jamais ouvrir la porte. On ne voit pas un soufflé monter depuis l'extérieur du four, mais on le sent : l'odeur passe de l'oeuf mouillé au pain chaud au moment où il culmine. Sortez-le alors, et portez-le vite. Un soufflé est une respiration retenue. Il n'attendra pas que l'invité ait fini de parler." },
    [1270635] = { "Des pinces de crabe, cassées et vidées, liées avec le moins de farine possible et frites en petites bouchées. La farine est une corde, pas un repas. Mettez-en trop et les bouchées ne sentent que le pain. Mettez-en juste assez et elles sentent la mer et la poêle. La saison des crabes, dit la recette. D'après moi, toutes les saisons sont celles des crabes, si l'on vit assez près de l'eau." },
    [1283400] = { "Le bois d'étoile brûle plus chaud et plus proprement que le bois commun, avec une odeur de résine et de givre. La recette vient des Cavernes des Lamentations, où les druides ont mal rêvé, et quelqu'un a décidé qu'un meilleur feu de camp valait le voyage. Empilez-le de la même façon et laissez-le retomber davantage avant de cuisiner, parce qu'un feu plus chaud pardonne moins. Quand les braises blanchissent sur les bords, il est temps de cuisiner." },
    [1291341] = { "Des bûches épaisses, lentes à prendre et lentes à mourir, un feu pour toute une soirée. Disposez-les en carré avec un passage pour l'air et allumez le petit bois dessous. Puis attendez. L'odeur change quand il est prêt, de la fumée verte à la fumée sèche, de l'âcre au doux. C'est le feu d'un spécialiste, et la leçon d'un spécialiste : la meilleure chaleur est celle qu'on a attendue. On ne m'a pas vendu cette recette. Je le bâtis d'après ce qu'on m'en a appris, et on me l'a bien appris." },
    [1294014] = { "Des baies d'Hyjal, trois mesures, réduites lentement avec des épices apaisantes jusqu'à ce qu'une goutte sur une assiette froide se ride quand on la pousse. L'odeur est le meilleur moment, et je peux vous le dire avec une certaine autorité : fruit sombre et épice chaude, si sucrée qu'elle en est presque bruyante. Les ours pillent les buissons pour ces baies, dit la recette. Je ferais pareil, si j'étais un ours." },
    [1295805] = { "Un ragoût du rivage : du crabe, des yeux de murloc et des épices fortes. Les yeux épaississent le bouillon, alors ne les enlevez pas pour ménager qui que ce soit. Le crabe entre à la fin, pour rester doux. L'odeur est celle de la mer avant qu'on l'ait rangée, sel, algue et quelque chose d'encore vivant. Mes élèves se pincent le nez la première fois. La deuxième fois, ils demandent un bol." },
    [1295834] = { "Du sanglier rôti sur l'os avec un peu d'épices douces et rien d'autre, comme les cuisines de ferme l'ont toujours fait. La recette vient des Rives Claires, de quelqu'un qui avait visiblement des gens affamés à nourrir. Rôtissez jusqu'à ce que la graisse crépite et que l'odeur passe de la viande à la noisette. Ne le décorez pas. Un plat simple est une promesse que la viande est bonne, et le cuisinier qui ajoute des choses avoue qu'elle ne l'était pas." },
    [1319313] = { "Un poisson en armure. Les plaques s'enlèvent avec un couteau lourd et beaucoup de patience, et la chair dessous est ferme et pâle, comme celle d'un homard. Des épices apaisantes, une chaleur modérée, et sans hâte. Les choses en armure mettent du temps à cuire, comme vous le diront les gardes noirs, et ce n'est pas des poissons qu'ils parlent. Servez-le dans ses propres plaques, lavées. Cela fait sourire les gens." },
  },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Hurlevent"] = "Stormwind", ["Comté-de-l’Or"] = "Goldshire", ["Comté-de-l'Or"] = "Goldshire", ["Fossoyeuse"] = "Undercity", ["Forgefer"] = "Ironforge", ["Orneval"] = "Ashenvale", ["Cabestan"] = "Ratchet", ["Hautebrande"] = "Hillsbrad", ["Austrivage"] = "Southshore", ["Comté-du-Lac"] = "Lakeshire", ["Sombre-Comté"] = "Darkshire", ["Hautes-terres Arathies"] = "Hautes-terres d'Arathi" }
